select
  'food-safety-and-sanitation',
  null,
  'Food Safety and Sanitation',
  'Food Safety and Sanitation',
  'This course introduces the science, law, systems, and managerial practices used to prevent foodborne illness and protect food in hospitality operations. Students identify biological, chemical, physical, and allergen hazards; apply employee health and hygiene controls; manage time and temperature; protect food through purchasing, receiving, storage, preparation, cooking, cooling, holding, service, delivery, and catering; design cleaning, sanitation, pest, facility, and utility controls; build HACCP and active-managerial-control systems; interpret inspection findings; strengthen food-safety culture; and respond to complaints, outbreaks, recalls, and emergencies. Applied laboratories and case exercises prepare students for an accredited food protection manager examination while emphasizing that certification complements—not replaces—competent daily management.',
  $fsafjson${"slug": "food-safety-and-sanitation", "title": "Food Safety and Sanitation", "description": "This course introduces the science, law, systems, and managerial practices used to prevent foodborne illness and protect food in hospitality operations. Students identify biological, chemical, physical, and allergen hazards; apply employee health and hygiene controls; manage time and temperature; protect food through purchasing, receiving, storage, preparation, cooking, cooling, holding, service, delivery, and catering; design cleaning, sanitation, pest, facility, and utility controls; build HACCP and active-managerial-control systems; interpret inspection findings; strengthen food-safety culture; and respond to complaints, outbreaks, recalls, and emergencies. Applied laboratories and case exercises prepare students for an accredited food protection manager examination while emphasizing that certification complements—not replaces—competent daily management.", "topics": [{"id": "e48b3980-c170-49a8-9338-27972b8cfaf0", "type": "topic", "title": "Food Safety Foundations, Public Health, and Regulation", "description": "This section frames food safety as a public-health and management responsibility. Students learn how science, law, operations, and human behavior work together to prevent illness and protect guests, employees, and the business.", "children": [{"id": "5172ba2d-bdd0-4c8a-a620-37dbae9e6956", "type": "subtopic", "title": "Burden and pathways of foodborne illness", "children": [{"id": "b31e446c-ebe6-44c3-b362-ae47d23a3b11", "type": "concept", "title": "Foodborne infection, intoxication, toxin-mediated infection, injury, and long-term sequelae"}, {"id": "0769f073-171e-4278-8296-6f17c0527d5c", "type": "concept", "title": "Sporadic illness, clusters, outbreaks, endemic disease, and underreporting"}, {"id": "f614022a-c9f2-41c9-badd-6401ec733d05", "type": "concept", "title": "Higher-risk populations and institutional foodservice responsibilities"}], "description": "Students begin with why controls matter: foodborne disease can cause severe harm, disproportionately affect vulnerable populations, and damage trust and livelihoods."}, {"id": "69d6ef66-75d5-437d-b5d3-614995e8250b", "type": "subtopic", "title": "Farm-to-fork system and shared responsibility", "children": [{"id": "916be0d0-67e0-412a-a498-44277d8e706e", "type": "concept", "title": "Primary production, processing, distribution, retail, foodservice, delivery, and consumption"}, {"id": "96c2864f-b196-4763-a85a-ae8b73b69cb6", "type": "concept", "title": "Regulators, operators, certified managers, persons in charge, employees, suppliers, and guests"}, {"id": "91e5ace9-96bb-4417-93fa-193a51230682", "type": "concept", "title": "Prevention, detection, response, recovery, and continuous improvement"}], "description": "This subtopic shows that safety depends on linked controls from supplier through service and consumer handling."}, {"id": "991041bf-2c90-48ba-9612-c9d6b496d42e", "type": "subtopic", "title": "Regulatory framework and code literacy", "children": [{"id": "31494b70-b1fd-48bb-9b87-66be4aaada5d", "type": "concept", "title": "FDA Food Code as a U.S. model; state, local, tribal, territorial, and federal adoption"}, {"id": "355fae34-2da4-45ab-8972-abce7c23cda3", "type": "concept", "title": "Competent authorities and local requirements outside the United States"}, {"id": "a84659dc-ff94-43b9-ac87-51475974fc21", "type": "concept", "title": "Priority items, priority foundation items, core items, permits, variances, and enforcement"}], "description": "Students learn to find and interpret the rules actually adopted in their jurisdiction rather than assuming a model code is automatically law."}]}, {"id": "a724b0df-cb81-445f-afe7-cb8093200d37", "type": "topic", "title": "Biological Hazards, Pathogens, and Contamination", "description": "This section builds the microbiological foundation needed to understand why specific operational controls work. Students focus on hazard behavior and control—not memorizing disconnected organism lists.", "children": [{"id": "1ff84458-31bd-4ca2-b68d-7c87fe7f44f9", "type": "subtopic", "title": "Types of biological hazards", "children": [{"id": "2c6c0a26-a99b-4f05-a75a-a8e0c57931a2", "type": "concept", "title": "Bacteria, viruses, parasites, fungi, prions, and biological toxins"}, {"id": "d02f19ef-f3e0-4eb1-82c5-809df5198df7", "type": "concept", "title": "Spore-formers, toxin producers, acid tolerance, and environmental persistence"}, {"id": "510dbb7f-c86b-4207-8e6b-44274db9e07d", "type": "concept", "title": "Foodborne versus person-to-person and environmental transmission"}], "description": "Students distinguish organisms and agents by survival, growth, transmission, and control needs."}, {"id": "6324544b-d7af-48bf-9613-a353db930c9f", "type": "subtopic", "title": "Priority pathogens and food associations", "children": [{"id": "3fad4cf4-09d1-47f9-9c69-1c5444a20944", "type": "concept", "title": "Norovirus, Salmonella, Shiga toxin-producing E. coli, Campylobacter, Listeria monocytogenes, Clostridium perfringens, Clostridium botulinum, Bacillus cereus, Staphylococcus aureus, and hepatitis A"}, {"id": "c7eea06c-8863-4c00-ad9c-918cbe2eef3d", "type": "concept", "title": "Raw/undercooked animal foods, produce, ready-to-eat foods, rice and grains, seafood, and low-oxygen foods"}, {"id": "18457c6a-0100-4cae-a0c5-78c2ca78fdca", "type": "concept", "title": "Incubation, duration, dose, asymptomatic shedding, and vulnerable populations"}], "description": "This subtopic connects representative hazards to foods, symptoms, severity, and prevention while avoiding false certainty about a single source."}, {"id": "2ad5a4ae-5fda-4150-bbd5-616172328e2d", "type": "subtopic", "title": "Contamination routes and growth conditions", "children": [{"id": "054af8c2-cf28-410e-8b95-44fdfccd2b27", "type": "concept", "title": "Source contamination, hands, surfaces, utensils, droplets/aerosols, pests, water, soil, and waste"}, {"id": "e89cbdbd-3972-42f4-9113-6fef5e024d70", "type": "concept", "title": "Cross-contamination and environmental niches/biofilms"}, {"id": "549f7ae1-cffa-442a-ae58-7443ac48ee39", "type": "concept", "title": "Food, acidity, time, temperature, oxygen, and moisture as growth factors"}], "description": "Students map how hazards enter, move through, survive, and multiply in an operation."}]}, {"id": "f466b63f-e8ba-44bd-a55c-fdddc3e56b71", "type": "topic", "title": "Personal Hygiene, Employee Health, and Human Factors", "description": "Food handlers are essential control partners, not simply sources of risk. This section develops scientifically grounded hygiene, illness-reporting, and work-design practices that employees can realistically follow.", "children": [{"id": "b2c7dfb7-80c1-473c-90ab-9e68aaf2aefc", "type": "subtopic", "title": "Hand hygiene and hygienic practices", "children": [{"id": "6f7e5098-d760-4a8c-8ef9-01bfed47312a", "type": "concept", "title": "Handwashing steps, sinks, supplies, timing, drying, and monitoring"}, {"id": "d2a91d44-32eb-4ca8-b891-46a3d26bc148", "type": "concept", "title": "Bare-hand contact with ready-to-eat food; gloves and utensils"}, {"id": "d174ce93-1d6c-4e94-a86b-09b38722aa62", "type": "concept", "title": "Fingernails, jewelry, clothing, hair restraints, wounds, eating, drinking, and tobacco/vaping"}], "description": "Students learn when and how hygiene interrupts transmission and why gloves never replace correct handwashing."}, {"id": "c53f5460-887f-42c0-b70e-48f811266544", "type": "subtopic", "title": "Employee health program", "children": [{"id": "eb5b6394-7e63-499f-a23e-712cb6e6cf43", "type": "concept", "title": "Vomiting, diarrhea, jaundice, sore throat with fever, infected lesions, and jurisdiction-specific reportable conditions"}, {"id": "d3d9e5ba-497e-47cb-8e10-ee3067c360dc", "type": "concept", "title": "Conditional employees, food employees, person in charge, agreements, records, and return-to-work rules"}, {"id": "44ef12a0-60f9-48b4-83ae-d28b2275cfee", "type": "concept", "title": "Paid sick leave, fear of discipline, staffing pressure, language access, and non-retaliation"}], "description": "This subtopic connects symptoms, diagnoses, exposure, reporting, restriction, exclusion, clearance, and confidentiality."}, {"id": "e37d669e-d6bd-4ad8-b22e-74197e668beb", "type": "subtopic", "title": "Human factors and behavior", "children": [{"id": "c0765fba-3441-4d22-8468-768a23840099", "type": "concept", "title": "Workload, fatigue, heat, time pressure, staffing, equipment placement, and production targets"}, {"id": "089dd067-79fa-4dbb-bdf7-fae86a8895e5", "type": "concept", "title": "Norms, cues, feedback, supervision, incentives, and psychological safety"}, {"id": "7e6c49c1-e8ba-4064-b41a-c99ffe9aacc6", "type": "concept", "title": "Observation, coaching, error-proofing, and just-culture responses"}], "description": "Students examine why knowledge alone does not produce safe practice and how systems can make the safe action easier."}]}, {"id": "07df9024-8796-4787-be48-7a19c1074d11", "type": "topic", "title": "Allergens, Chemical Hazards, and Physical Hazards", "description": "Not all food-safety hazards are microorganisms. This section prepares students to control allergens, toxic chemicals, natural toxins, and foreign objects through procurement, labeling, separation, communication, and incident readiness.", "children": [{"id": "3436b361-a95a-41b3-92f8-b87047edd181", "type": "subtopic", "title": "Food-allergen management", "children": [{"id": "ca98819c-5359-4fad-8da1-eeab9fb7545d", "type": "concept", "title": "Jurisdiction-specific major allergens; sesame in the current U.S. framework"}, {"id": "e22ef47d-d308-4309-8fa3-ddeaeb4a5acf", "type": "concept", "title": "Ingredient and label review, recipe control, substitutions, supplier changes, and rework"}, {"id": "63b148e9-c76c-4665-b49c-f1e820af340d", "type": "concept", "title": "Order communication, dedicated tools/areas where needed, cleaning validation, plating, delivery, and emergency response"}], "description": "Students learn to prevent allergen cross-contact and communicate accurately from supplier label to guest service."}, {"id": "072d3db1-f956-4a2b-bced-faebb9733082", "type": "subtopic", "title": "Chemical hazards and toxic substances", "children": [{"id": "7c3d9985-9fd9-4cdf-8556-66d2c1302c5a", "type": "concept", "title": "Cleaning and sanitizing chemicals, pesticides, lubricants, metals, additives, and migration from equipment/packaging"}, {"id": "00dbed01-7007-40eb-99eb-2f1c35d1f828", "type": "concept", "title": "Natural toxins, histamine/scombrotoxin, ciguatoxin, mycotoxins, and toxic mushrooms/plants"}, {"id": "7261c796-ee16-455f-aae4-378c5a4ff29b", "type": "concept", "title": "Original containers, labels, safety data sheets, storage, concentration, rinsing, and approved use"}], "description": "This subtopic covers chemicals that may be naturally present, intentionally used, or accidentally introduced."}, {"id": "717cb781-8079-4797-85c8-fb0e5b3878a2", "type": "subtopic", "title": "Physical hazards and foreign material", "children": [{"id": "f21ff270-780f-47d9-a200-8f2e16ed5f08", "type": "concept", "title": "Glass, hard plastic, metal, wood, stones, jewelry, bone, pits, packaging, and personal items"}, {"id": "6946ff6b-0eb8-4ad6-92cd-80665e62950b", "type": "concept", "title": "Preventive maintenance, protective covers, receiving inspection, breakage procedures, and product holds"}, {"id": "1567712c-5615-4151-b8f2-a34964d54e13", "type": "concept", "title": "Customer complaint assessment, documentation, disposition, and escalation"}], "description": "Students learn to identify sources and design prevention and response controls."}]}, {"id": "61f6bfc5-8e1d-4f28-b516-df6bd8d25ec7", "type": "topic", "title": "Time and Temperature Control", "description": "Time and temperature are among the most powerful foodservice controls. Students learn the science, measurement, monitoring, and corrective actions needed across the entire flow of food.", "children": [{"id": "725b44ca-fb05-4746-b233-c56cb9ff03c8", "type": "subtopic", "title": "Temperature danger and pathogen behavior", "children": [{"id": "57f6d533-b449-4a5e-9b35-f4348c9fdaad", "type": "concept", "title": "Time/temperature control for safety food and jurisdictional definitions"}, {"id": "b396a1cb-19a6-4a8b-9543-bec30b0c0ee2", "type": "concept", "title": "Growth curves, lag time, cumulative exposure, and heat resistance"}, {"id": "69d069e2-3a25-4e6a-87fc-567218be54c0", "type": "concept", "title": "Toxin hazards that cooking may not reverse"}], "description": "Students connect growth, survival, spore germination, and toxin formation to operational decisions."}, {"id": "ef512d99-db06-40cc-959c-436705a96929", "type": "subtopic", "title": "Thermometers and measurement systems", "children": [{"id": "190d4b3c-3e68-4859-8de1-2f5c932bdfe6", "type": "concept", "title": "Bimetallic stem, thermistor/thermocouple, infrared, probe types, data loggers, and equipment gauges"}, {"id": "51b3a1fb-7f9c-430a-ac50-0f0fdb311e4b", "type": "concept", "title": "Calibration/verification methods, accuracy, response time, measurement location, and uncertainty"}, {"id": "6c311f54-49f4-4cfd-a615-eb0b4c5ea3e9", "type": "concept", "title": "Cleaning/sanitizing probes, records, alarms, and corrective action"}], "description": "This subtopic develops confidence in selecting, placing, calibrating, using, cleaning, and interpreting instruments."}, {"id": "712983c5-a548-42dc-abbd-6ca58593b39b", "type": "subtopic", "title": "Cold and hot control through the process", "children": [{"id": "dc7e9a88-2648-4ce7-b20c-97e40d71f810", "type": "concept", "title": "Receiving, storage, thawing, preparation, cooking, hot holding, cold holding, cooling, reheating, and service"}, {"id": "3e704aed-61ef-497b-979f-47afd198e84d", "type": "concept", "title": "Time as a public-health control, labeling, discard times, written procedures, and monitoring"}, {"id": "e7d7cf57-d7d8-4076-b6a0-d761b7b82cf4", "type": "concept", "title": "Batch size, shallow pans, ice baths, blast chilling, heat transfer, equipment loading, and verification"}], "description": "Students apply the currently adopted code limits and approved procedures rather than relying on memory alone."}]}, {"id": "20e9ebd8-df2b-4742-9c94-e89a905a4738", "type": "topic", "title": "Approved Sources, Receiving, Storage, and Traceability", "description": "Food safety begins before the delivery arrives. This section teaches students to qualify suppliers, verify receiving conditions, maintain storage controls, and preserve records needed to trace and isolate product.", "children": [{"id": "2996f7c3-29d6-403a-851e-e594df3f6ce6", "type": "subtopic", "title": "Approved suppliers and specifications", "children": [{"id": "6601448d-533d-40bc-972a-8e1f99de035b", "type": "concept", "title": "Licensing/inspection status, third-party assurances, recall capability, allergen and ingredient data, and cold-chain controls"}, {"id": "1e40f7ba-638a-4953-a46f-6f486250cc26", "type": "concept", "title": "Product specifications, substitutions, rejection criteria, and supplier performance"}, {"id": "a56e5b3a-be63-4d21-84a3-df4ed92c0980", "type": "concept", "title": "Shellstock, game, wild mushrooms, donated food, and other jurisdiction-sensitive sources"}], "description": "Students learn to source from lawful, capable suppliers and define safety requirements in purchasing documents."}, {"id": "407649ab-79c2-49bb-8603-728c4c8208b6", "type": "subtopic", "title": "Receiving and acceptance", "children": [{"id": "0db5d7de-80eb-40e8-8af2-bd3f3ca3bbf9", "type": "concept", "title": "Vehicle and package condition, seals, temperatures, dates, labels, documentation, pests, and evidence of thaw/refreeze"}, {"id": "3f47511b-c43f-4511-978c-befce5cc9411", "type": "concept", "title": "Sampling plans, calibrated instruments, rejection, segregation, and incident escalation"}, {"id": "d2da9048-dfb2-4ec3-a42e-c3e2308d7ad8", "type": "concept", "title": "Receiving schedule, staffing, dock hygiene, and rapid put-away"}], "description": "This subtopic turns the loading dock into an active control point."}, {"id": "2e1149de-0124-472c-acac-185da8a3e85f", "type": "subtopic", "title": "Storage and stock rotation", "children": [{"id": "cdbfaaf0-aaf6-43c8-87ab-ab5f56a044be", "type": "concept", "title": "Separation of raw and ready-to-eat foods; covered, labeled, and elevated storage"}, {"id": "76ee1fdf-d10e-47bb-a54f-3706020b1862", "type": "concept", "title": "Date marking, first-in/first-out or first-expired/first-out, shelf life, and discard"}, {"id": "28adcaf8-28d0-4823-99cd-d5ab468de073", "type": "concept", "title": "Temperature mapping, overcrowding, air flow, power loss, and inventory checks"}], "description": "Students organize dry, refrigerated, frozen, chemical, and protected storage to prevent contamination and loss of control."}, {"id": "5de72de1-2734-422c-af60-fdbe5ea56dd9", "type": "subtopic", "title": "Traceability and recall readiness", "children": [{"id": "0c29a663-ba63-4831-ac9e-8abd25120de7", "type": "concept", "title": "One-step-forward/one-step-back concepts and internal lot/location tracking"}, {"id": "4e445861-07f8-4c66-afda-0389b65f65f9", "type": "concept", "title": "Shellstock tags, invoices, production records, labels, and digital systems"}, {"id": "0a42fbc9-0ebc-4ac7-bf60-9146d9a2eb4e", "type": "concept", "title": "Product hold, inventory reconciliation, recall checks, disposition, and effectiveness verification"}], "description": "Students maintain source, lot, date, quantity, and disposition information so affected food can be found quickly."}]}, {"id": "6643a077-44b0-45e9-a583-025d0997b5a7", "type": "topic", "title": "Safe Preparation, Cooking, Cooling, Reheating, Holding, and Service", "description": "This section integrates controls across kitchen production. Students learn to prevent cross-contamination, achieve validated lethality, limit growth, and protect food through service and leftovers.", "children": [{"id": "d6a82c7d-efb6-416a-8d6a-c47d49020421", "type": "subtopic", "title": "Preparation and cross-contamination prevention", "children": [{"id": "73a8f8c0-7ef6-4e5f-96a1-a65f8d272cca", "type": "concept", "title": "Raw-to-ready-to-eat separation, color coding, dedicated equipment, and preparation scheduling"}, {"id": "ae04d103-1037-453e-93dc-6112ac9b49e8", "type": "concept", "title": "Thawing methods, washing produce, pooled eggs, batters/breading, and handling ready-to-eat foods"}, {"id": "f7f421a6-3cef-4f26-9392-d7164c0ce793", "type": "concept", "title": "Small batches, exposure time, return to control, and corrective action"}], "description": "Students design workflow, zoning, sequencing, utensils, and cleaning around the separation of hazards."}, {"id": "0853f977-976e-456e-b270-f5f107f2a3a8", "type": "subtopic", "title": "Cooking and process controls", "children": [{"id": "68277515-fa42-46ed-a292-58eb67208f4d", "type": "concept", "title": "Minimum internal cooking parameters and approved alternatives"}, {"id": "3ed388ab-f57d-4b0d-ba04-f8dc0d0f3ded", "type": "concept", "title": "Whole-muscle, ground, injected/tenderized, poultry, eggs, seafood, plant foods, microwave, and roasts"}, {"id": "206200f3-7466-4dae-8bbc-7e1ef810fcbf", "type": "concept", "title": "Probe placement, multiple measurements, carryover, consumer advisories, and recordkeeping"}], "description": "This subtopic connects food type and process to the required, measured endpoint in the adopted code."}, {"id": "60624a13-c597-45ef-af34-c430105dd6a0", "type": "subtopic", "title": "Cooling, reheating, and holding", "children": [{"id": "63aa4418-1c71-4e3f-92bf-07b547e942b2", "type": "concept", "title": "Two-stage cooling concepts, rapid methods, uncovered/loosely covered cooling as allowed, and verification"}, {"id": "1518f577-8f4b-4f26-819e-563a1f63d649", "type": "concept", "title": "Reheating for hot holding versus immediate service"}, {"id": "d34332f1-364a-46c1-be31-ab568576d223", "type": "concept", "title": "Hot/cold holding equipment, stirring, lids, batch replacement, and corrective action"}], "description": "Students learn why large batches fail and how equipment, container geometry, and monitoring change outcomes."}, {"id": "4c2743c5-b367-4ec1-abd9-a76a7a3b42e4", "type": "subtopic", "title": "Service, displays, and leftovers", "children": [{"id": "c4f846f7-e55e-4601-90d1-8af837f18d49", "type": "concept", "title": "Self-service, buffets, sneeze guards, utensils, consumer contamination, and replenishment"}, {"id": "3167224a-5498-433c-b380-9dc7321b88e4", "type": "concept", "title": "Return/re-service restrictions, takeout packaging, delivery handoff, and guest instructions"}, {"id": "4492547a-784d-4713-b630-4704eb552afe", "type": "concept", "title": "Leftover decisions, donation, cooling, labeling, transport, and approved disposition"}], "description": "This subtopic protects food at the last operational mile."}]}, {"id": "fc44fed3-f8be-4650-9e9e-1765e31f40ce", "type": "topic", "title": "Cleaning, Sanitizing, and Environmental Hygiene", "description": "Cleaning removes soil; sanitizing reduces microorganisms to safe levels. Students learn to design, execute, verify, and improve sanitation programs appropriate to food-contact and non-food-contact environments.", "children": [{"id": "b27c61f3-339e-4688-ad10-df0f31a3faa1", "type": "subtopic", "title": "Cleaning chemistry and mechanics", "children": [{"id": "95b18000-e2cb-40e5-b743-310b295812ca", "type": "concept", "title": "Fats, proteins, carbohydrates, minerals, biofilms, and allergen residues"}, {"id": "f641557e-59f1-4aa8-afca-06af26d3398c", "type": "concept", "title": "Detergents, degreasers, acids, alkalis, enzymes, and compatibility"}, {"id": "5ae7984e-ff9d-4064-9de1-83ea9a6d933c", "type": "concept", "title": "Pre-clean, wash, rinse, inspect, sanitize where required, and air-dry"}], "description": "Students connect soil type, surface, water, time, temperature, chemistry, and mechanical action to effective cleaning."}, {"id": "ec7b9c4e-56a4-4708-aa70-b2e044df8915", "type": "subtopic", "title": "Sanitization methods and control", "children": [{"id": "977e7b1b-9940-4ed8-8d59-a63aafd7fd72", "type": "concept", "title": "Concentration, contact time, temperature, pH, water hardness, and organic load"}, {"id": "fb4ee515-1f36-4f9b-854b-51cd0f6b6408", "type": "concept", "title": "Test kits, automated dispensers, three-compartment sinks, dishmachines, and manual methods"}, {"id": "e046f0d5-df08-4f12-b6f2-5779dcc1021d", "type": "concept", "title": "Too weak, too strong, mixing hazards, residues, and corrective action"}], "description": "This subtopic develops correct use of heat and approved chemical sanitizers."}, {"id": "15b8baf3-fd2a-421d-b01b-7f9e3a9f39a0", "type": "subtopic", "title": "Master sanitation program and verification", "children": [{"id": "ed3e09da-e22a-4da4-adfb-a2c9e505360a", "type": "concept", "title": "Food-contact surfaces, in-use utensils, ice machines, beverage systems, slicers, drains, hoods, coolers, and high-touch points"}, {"id": "f2a654df-1b43-4f14-9ea8-4640c1bfcaee", "type": "concept", "title": "Clean-in-place, disassembly, lockout/tagout interfaces, and sanitation standard operating procedures"}, {"id": "a149c786-e222-4125-976d-f1caf4dcb510", "type": "concept", "title": "Visual inspection, records, ATP/protein/allergen tools, microbiological testing where appropriate, trends, and corrective action"}], "description": "Students create a risk-based schedule that assigns what, how, when, who, and how performance is verified."}]}, {"id": "06985a12-7264-46d4-b130-2015803d0318", "type": "topic", "title": "Facilities, Equipment, Water, Waste, and Pest Management", "description": "Safe food depends on the built environment and utilities. This section teaches students to evaluate hygienic design, maintain potable water and waste systems, and use integrated pest management.", "children": [{"id": "d26e3e0a-4d0d-4711-bcd7-43fff17867f0", "type": "subtopic", "title": "Hygienic facility and equipment design", "children": [{"id": "022302ba-8f5a-4d9b-bca8-6a544adff25d", "type": "concept", "title": "Smooth, durable, nonabsorbent, corrosion-resistant, accessible, and cleanable surfaces"}, {"id": "2b165e49-251e-43f7-8734-9b75f59a9388", "type": "concept", "title": "Equipment certification, installation, spacing, sealing, drainage, ventilation, lighting, and hand sinks"}, {"id": "7d7298d2-d9c9-418b-b619-952920bb9121", "type": "concept", "title": "Raw/ready-to-eat zones, employee areas, storage, warewashing, refuse, and traffic patterns"}], "description": "Students identify design features that support cleaning, separation, maintenance, and safe flow."}, {"id": "a1aa7c6d-0862-451c-9eac-2c72277fc15a", "type": "subtopic", "title": "Water, ice, plumbing, sewage, and waste", "children": [{"id": "3877fde0-a2ba-4f2e-a47e-4df6b7f49afc", "type": "concept", "title": "Potable water, ice as food, hoses, cross-connections, air gaps, backflow devices, and grease systems"}, {"id": "e332390c-9728-450b-8fae-1fab2c261d5b", "type": "concept", "title": "Sewage backups, drain overflows, condensation, leaks, and standing water"}, {"id": "1903fe1c-0eb3-4e8c-86fe-6705d300a28c", "type": "concept", "title": "Waste segregation, covered containers, used oil, rendering, composting, and refuse area hygiene"}], "description": "This subtopic emphasizes safe sources, backflow prevention, drainage, and rapid response to utility failures."}, {"id": "39115434-e731-4b76-9595-cfdd6c096501", "type": "subtopic", "title": "Integrated pest management", "children": [{"id": "374f319d-b686-49cb-9a00-0377b17de1b1", "type": "concept", "title": "Entry points, harborage, food/water sources, doors, screens, seals, and landscaping"}, {"id": "041b6f7f-bba6-443a-9099-097395ed3a9a", "type": "concept", "title": "Monitoring devices, pest evidence, maps, trend logs, and contractor reports"}, {"id": "8c3704f8-d9db-40fe-9709-d2f1a804366a", "type": "concept", "title": "Approved pesticide use, preparation protection, dead-pest removal, root-cause correction, and verification"}], "description": "Students focus on exclusion, sanitation, monitoring, and targeted control rather than routine pesticide dependence."}, {"id": "82f0d03f-3424-41da-ab2f-faf545c0a0c4", "type": "subtopic", "title": "Preventive maintenance and utilities resilience", "children": [{"id": "9f2c555b-96a1-405c-8c50-b09878f9ae80", "type": "concept", "title": "Gaskets, thermometers, refrigeration, hot water, dishmachines, drains, and food-contact surface integrity"}, {"id": "d43b1f7a-42b4-4798-a60f-5cb03ddca6e0", "type": "concept", "title": "Work orders, temporary controls, out-of-service decisions, and post-repair cleaning"}, {"id": "8bcddd8a-0c33-477c-b4d4-1cc8e26f8988", "type": "concept", "title": "Power, water, gas, refrigeration, and ventilation interruption plans"}], "description": "Students connect equipment condition and contingency planning to food-safety control."}]}, {"id": "0b7ec4ca-cceb-4e59-b598-ec40ebad1625", "type": "topic", "title": "HACCP, Preventive Controls, and Active Managerial Control", "description": "This section turns hazard knowledge into a preventive management system. Students learn to analyze processes, establish controls, verify performance, and take corrective action before unsafe food reaches a guest.", "children": [{"id": "b55b1175-5b48-49b6-b933-e158b5bc2212", "type": "subtopic", "title": "Prerequisite programs and process mapping", "children": [{"id": "fc01d0be-7f4e-4103-a36a-2816fd0993aa", "type": "concept", "title": "Approved sources, hygiene, sanitation, maintenance, pest control, training, allergen, and supplier programs"}, {"id": "a221930b-7118-4f46-b6e7-b86cc5f9fe65", "type": "concept", "title": "Product description, intended use, consumers, flow diagram, on-site confirmation, and process categories"}, {"id": "db656796-6d5c-46ba-bd7b-d6b08657da72", "type": "concept", "title": "Operational prerequisite programs and jurisdictional terminology"}], "description": "Students first establish dependable basic conditions and a truthful picture of how food flows."}, {"id": "f7fc174e-0999-4454-9e30-b0579bea5c30", "type": "subtopic", "title": "Seven HACCP principles", "children": [{"id": "d359823a-cdae-44d4-83f4-fc4ea974dbfa", "type": "concept", "title": "Hazard analysis and control-measure selection"}, {"id": "72711732-6a54-4730-a37f-20e027b4e791", "type": "concept", "title": "Critical control points, validated critical limits, monitoring, corrective action, verification, and records"}, {"id": "d0c614d2-c95c-4aa4-a461-6a00bb8d359a", "type": "concept", "title": "Validation versus verification; deviations, disposition, and reassessment"}], "description": "This subtopic teaches a disciplined method for significant hazard control."}, {"id": "e474b76f-7774-447e-b1fd-29abd1d2ecf9", "type": "subtopic", "title": "Active managerial control", "children": [{"id": "9537d14d-359d-406b-9f26-e41b736c5585", "type": "concept", "title": "Demonstration of knowledge, employee health, approved sources, cooking, holding, contaminated equipment, and other risk factors"}, {"id": "019d8630-d4c3-41b0-83e2-9d9555a4a307", "type": "concept", "title": "Daily checks, manager observations, exception reporting, and ownership"}, {"id": "ff0216f2-5084-4c7e-b4a5-f85ed634b816", "type": "concept", "title": "Trend analysis, focused interventions, accountability, and continuous improvement"}], "description": "Students learn to manage the common risk factors every shift through policies, training, monitoring, and corrective action."}, {"id": "b84a6e73-1e0c-4bbb-80fc-f14a62e40dd5", "type": "subtopic", "title": "Special processes and variances", "children": [{"id": "e5c9a374-4cb1-4562-81d1-29a6a5d26f4a", "type": "concept", "title": "Variance triggers and HACCP plan requirements"}, {"id": "a735332e-f916-4278-9495-8ce0f51e3980", "type": "concept", "title": "Reduced-oxygen packaging, sous vide, cook-chill, smoking for preservation, curing, custom processing, live molluscan shellfish tanks, sprouting, and acidification"}, {"id": "44431d24-fe1c-438a-acfb-c4228414308e", "type": "concept", "title": "Scientific support, validation, labeling, shelf life, monitoring, records, and regulator consultation"}], "description": "This subtopic makes clear that reduced-oxygen packaging, curing, acidification, sprouting, and other processes require specialized controls and often regulatory approval."}]}, {"id": "cab95990-0e69-4224-91c4-72c08f26623d", "type": "topic", "title": "Inspection, Compliance, Documentation, and Corrective Action", "description": "Regulatory inspections are snapshots; food safety must be managed continuously. Students learn to prepare through daily control, communicate professionally, interpret findings, and close the loop on violations.", "children": [{"id": "a54a16f0-f5c8-4177-8b43-90c251c77ab2", "type": "subtopic", "title": "Risk-based inspection and regulatory interaction", "children": [{"id": "0e3856f4-d5d5-40db-a4da-b73529c8eb02", "type": "concept", "title": "Preoperational and operational observations, temperatures, interviews, records, sampling, and embargo/hold authorities"}, {"id": "4327c2d8-5095-4a29-8db4-5c3be617d09e", "type": "concept", "title": "Priority classifications, compliance timeframes, follow-up, enforcement, appeal, and due process"}, {"id": "a2157646-89c3-49cf-979f-15ff70e77cb3", "type": "concept", "title": "Cooperation, truthful records, employee support, note taking, and escalation to leadership/counsel"}], "description": "Students understand inspection purpose, methods, evidence, and professional responsibilities."}, {"id": "174aa235-cffb-42e9-862f-a46f5386eabe", "type": "subtopic", "title": "Records and evidence", "children": [{"id": "895dabed-61e8-4e90-bde7-48e17d3a4aa2", "type": "concept", "title": "Receiving, temperature, cooling, sanitizer, employee health, training, cleaning, pest, maintenance, allergen, and corrective-action records"}, {"id": "4ae0fc75-181d-43e4-aab2-e64d5e905e9c", "type": "concept", "title": "Legibility, timestamps, instrument/lot identification, signatures, electronic controls, retention, and privacy"}, {"id": "5e0fb597-0da9-4a75-8123-ece2d91f5d4e", "type": "concept", "title": "Review by exception, falsification risk, record availability, and trend analysis"}], "description": "This subtopic focuses on concise, accurate documentation that supports control rather than paperwork for its own sake."}, {"id": "985d9da8-e3a3-4933-b601-0939ab683dcc", "type": "subtopic", "title": "Corrective and preventive action", "children": [{"id": "970aa245-96f6-4ca8-aa09-48a0213bbebb", "type": "concept", "title": "Immediate control, affected-food assessment, hold/discard/rework only when approved, and documentation"}, {"id": "9517a1f3-e737-40ff-a8ea-7eca3d8a9f76", "type": "concept", "title": "Five whys, fishbone, process mapping, contributing factors, and environmental antecedents"}, {"id": "8b4d5046-bb89-47c2-830a-9d8f16deca03", "type": "concept", "title": "Owner, due date, preventive change, effectiveness check, recurrence monitoring, and closure"}], "description": "Students move beyond fixing the immediate symptom to address system causes and verify effectiveness."}]}, {"id": "ac175b01-2988-4009-8901-19f71e80454b", "type": "topic", "title": "Food Safety Management Systems, Culture, and Training", "description": "World-class operations treat food safety as a managed organizational value. This section develops leadership practices that align policies, resources, behavior, data, and accountability.", "children": [{"id": "cb61e78e-cf94-4f1e-900c-e77aa6b27b87", "type": "subtopic", "title": "Food-safety policy and governance", "children": [{"id": "4670d81a-b520-44dd-ab76-ed13decacad0", "type": "concept", "title": "Policy, scope, legal register, objectives, roles, and management review"}, {"id": "3e9d512b-00e7-4c0a-8c3a-14af1de8dd21", "type": "concept", "title": "Person-in-charge coverage, certified food protection manager requirements, delegation, and succession"}, {"id": "4fc99d29-7ee1-4971-aaa3-6cdbfb948e2b", "type": "concept", "title": "Supplier standards, internal audits, incident review, and executive accountability"}], "description": "Students connect public-health commitments to roles, resources, metrics, and escalation."}, {"id": "098a0806-0ffe-4649-ad6a-c64c81787d80", "type": "subtopic", "title": "Food-safety culture", "children": [{"id": "a3b8f7b3-1c83-4e49-8d1a-831d3e8551fa", "type": "concept", "title": "Leadership credibility, communication, resources, risk awareness, employee voice, and consistency"}, {"id": "6162e2b7-f5c7-4137-8d48-62e912da0cab", "type": "concept", "title": "Just culture, stop-work authority, reporting without retaliation, and learning from near misses"}, {"id": "3700e688-9297-4062-87fc-0a8dc5100cfe", "type": "concept", "title": "Climate surveys, observations, turnover, sick-work behavior, and leading indicators"}], "description": "This subtopic examines what people believe is truly prioritized when production pressure conflicts with safety."}, {"id": "0e25c865-e725-4fd5-ba78-76d88403faed", "type": "subtopic", "title": "Training and competency", "children": [{"id": "b337af0c-1e04-4a15-a9ba-419551a4cdd7", "type": "concept", "title": "Onboarding, task training, refreshers, language/literacy access, demonstrations, and job aids"}, {"id": "4b3f8e48-9626-4acd-a50f-2c43f12fdd9f", "type": "concept", "title": "Explain–demonstrate–practice–observe–coach–verify cycle"}, {"id": "e65775ec-3bb9-456d-bdb3-e06746c72e04", "type": "concept", "title": "Knowledge tests, skills observation, retraining triggers, trainer qualification, and records"}], "description": "Students design role-specific learning that results in observable performance."}, {"id": "f60f55fe-4e25-4f1b-baef-8fcb74344731", "type": "subtopic", "title": "Certification and professional development", "children": [{"id": "62d047d1-5e5d-4710-96d4-68f6cdc0cfff", "type": "concept", "title": "Certification content domains and exam strategy"}, {"id": "7b7b9fa8-c330-4cc4-9270-4c6952d4f469", "type": "concept", "title": "Jurisdictional accreditation/recognition and renewal requirements"}, {"id": "ba6da822-2a29-40ec-8d8f-f1a62b90ee2f", "type": "concept", "title": "Continuing education, code updates, emerging hazards, and communities of practice"}], "description": "Students prepare for manager certification while understanding that passing an exam is only one element of competence."}]}, {"id": "656c3108-4b49-4b7d-b655-f8e78cc8296f", "type": "topic", "title": "Special Operations: Catering, Buffets, Delivery, Mobile, and High-Risk Service", "description": "Hospitality operations often move food away from the controlled kitchen. This section applies core principles to changing locations, delayed service, transportation, temporary utilities, and vulnerable populations.", "children": [{"id": "40b538cb-dfb3-45ba-8c65-325bdd384016", "type": "subtopic", "title": "Catering and off-site service", "children": [{"id": "deac5d09-9a63-43b9-8c3b-acf9d58bcd8f", "type": "concept", "title": "Approved prep site, transport containers, vehicle hygiene, route/time, temperature monitoring, and contingency"}, {"id": "d46d58b9-c9c3-40ff-b457-0f020181ccd5", "type": "concept", "title": "Temporary handwashing, warewashing, protected service, power, water, waste, and pest controls"}, {"id": "a4c9216a-dbd9-4b8c-8115-b82f56ab1fef", "type": "concept", "title": "Venue responsibility matrix, pre-event inspection, leftovers, and post-event reconciliation"}], "description": "Students plan the cold/hot chain, sanitation, water, transport, setup, service, and return/disposition before departure."}, {"id": "39bbf396-073d-46e1-b115-72b306a214bf", "type": "subtopic", "title": "Buffets, banquets, self-service, and room service", "children": [{"id": "3b450a3d-21d1-4eea-97a6-55e08a03e63f", "type": "concept", "title": "Small-batch replenishment, holding equipment, shields, utensils, labels, staff monitoring, and replacement rules"}, {"id": "29b4bdbf-de6c-4132-9432-49b086404f92", "type": "concept", "title": "Banquet plating lines, carts, elevators, remote pantries, room service, and tray retrieval"}, {"id": "9a6d325e-9a9d-4f33-b47c-a6b3db02ffae", "type": "concept", "title": "Allergen communication, vulnerable guests, and time control"}], "description": "This subtopic addresses high volume, long service periods, guest interaction, and batch management."}, {"id": "3b2edd81-db73-4ee3-b00e-0aa07b08f5c7", "type": "subtopic", "title": "Delivery, takeout, mobile, temporary, and outdoor foodservice", "children": [{"id": "14016461-ceb7-4882-bc34-4a80a0da757e", "type": "concept", "title": "Packaging suitability, separation, seals, labels, pickup shelving, driver handoff, and consumer instructions"}, {"id": "0bb62a10-5dda-4419-87f1-22bf8b4c705f", "type": "concept", "title": "Food trucks, temporary events, farmers markets, pop-ups, ghost kitchens, and shared kitchens"}, {"id": "d9b65588-7519-4f24-bfd6-65323915d108", "type": "concept", "title": "Weather, dust, pests, water/ice, refrigeration, generators, waste, permits, and closure thresholds"}], "description": "Students design for packaging, tamper evidence, last-mile delay, weather, limited utilities, and changing volume."}, {"id": "b1d68777-7865-4df6-afe2-4b3b4f0e33ca", "type": "subtopic", "title": "Highly susceptible populations and institutional settings", "children": [{"id": "84d1d3fe-cf4c-4585-ba5a-2a90db9a708e", "type": "concept", "title": "Hospitals, long-term care, childcare, and other jurisdiction-defined settings"}, {"id": "4a782a39-4ae8-439a-bd92-e51cdb396f54", "type": "concept", "title": "Restricted foods and processes, pasteurization, service controls, and employee health"}, {"id": "d3deff5b-eff0-4fdd-a2b3-3f59fbfaef6d", "type": "concept", "title": "Menu approval, clinical coordination, outbreak sensitivity, and documentation"}], "description": "Students apply enhanced restrictions and policies where consequences are greater."}]}, {"id": "6779e73b-31dd-4395-9a05-05c7670edf49", "type": "topic", "title": "Food Defense, Food Fraud, and Emergency Preparedness", "description": "Food safety programs must also address intentional harm, economically motivated adulteration, and disruptions to utilities or supply. Students learn proportionate prevention and response without creating fear or false certainty.", "children": [{"id": "e1b3b389-252e-4868-8e3c-e2b5e8d21af6", "type": "subtopic", "title": "Food defense", "children": [{"id": "f6e13dca-4744-4866-9021-13aa12bfeaf3", "type": "concept", "title": "Intentional adulteration, sabotage, threats, suspicious behavior, and insider risk"}, {"id": "38b0e8a8-df27-4cdd-9774-c7c1d4a9d48c", "type": "concept", "title": "Access control, visitor/vendor management, chemical and key control, seals, cameras where lawful, and reporting"}, {"id": "b265e7e5-af16-4da8-8968-c8352fb88d6e", "type": "concept", "title": "Threat assessment, law-enforcement/public-health coordination, evidence preservation, and employee safety"}], "description": "Students identify vulnerable points and practical protective measures appropriate to the operation."}, {"id": "b571bde1-d960-49e1-9e04-2efe9b24dcd3", "type": "subtopic", "title": "Food fraud and supply integrity", "children": [{"id": "8963fe8e-3767-4a45-bbb9-07e4f2029818", "type": "concept", "title": "Substitution, dilution, concealment, counterfeiting, mislabeling, and gray markets"}, {"id": "2d311773-b6cf-4451-981e-6bad9018580e", "type": "concept", "title": "Vulnerable commodities, supplier verification, specifications, testing/assurance, and traceability"}, {"id": "2f2cb9db-8bc7-4fb3-b19f-059564e6052f", "type": "concept", "title": "Escalation, product hold, legal review, and customer communication"}], "description": "This subtopic connects authenticity and economic deception to potential safety hazards and trust."}, {"id": "e298b992-7cb0-4bad-bd0d-e438a6b9f29d", "type": "subtopic", "title": "Emergency action planning", "children": [{"id": "5e57d3d9-332d-41a0-99d6-8a2ceec5bf25", "type": "concept", "title": "Power outage, refrigeration failure, water interruption/boil advisory, sewage backup, fire, flood, severe weather, contamination, and cyber outage"}, {"id": "8323df3b-744b-4036-a946-8573d130f216", "type": "concept", "title": "Assess–notify–isolate–monitor–document–recover sequence"}, {"id": "386b6ba0-d706-44e1-81c2-1d67ac21fde0", "type": "concept", "title": "Alternative water/ice, temporary menus, backup power, relocation, disposal, regulator approval, and reopening verification"}], "description": "Students create decision trees for events that may require restricted operations or closure."}]}, {"id": "7f31fa4a-e870-4ee6-9001-78388a55fbd1", "type": "topic", "title": "Outbreak Investigation, Recalls, Crisis Communication, and Recovery", "description": "The final section prepares future managers to recognize signals, protect people, cooperate with authorities, preserve evidence, communicate responsibly, and correct system failures.", "children": [{"id": "6ea04c95-6840-4d07-b4fc-f27864fb69a2", "type": "subtopic", "title": "Illness complaint and outbreak response", "children": [{"id": "10de32f7-b9ff-41d9-aa4d-620c385919ec", "type": "concept", "title": "Complaint intake: contact, foods, meal date/time, symptoms/onset, others ill, medical care, and reporter details"}, {"id": "fd6a91c1-18ac-4a34-a6c6-a0097de923c6", "type": "concept", "title": "Immediate manager notification, employee health review, implicated-food hold, records preservation, and regulator contact"}, {"id": "749e5155-1b20-4b45-a4ba-c15542bc3a8d", "type": "concept", "title": "Confidentiality, no retaliation, no speculative conclusions, and coordination with public health"}], "description": "Students learn to treat complaints seriously without diagnosing or admitting unsupported causation."}, {"id": "50eb39a9-2f9e-4ad8-bc7d-7692bee411bb", "type": "subtopic", "title": "Environmental assessment and epidemiologic support", "children": [{"id": "b74991c0-81c8-4284-92c9-e8b1411e1a53", "type": "concept", "title": "Case definition, interviews, line lists, descriptive epidemiology, traceback, sampling, and laboratory evidence"}, {"id": "01520963-6915-4a79-8c8e-e558bfe548bd", "type": "concept", "title": "Food-specific and system-level contributing factors"}, {"id": "8dedbb00-7154-45e0-86b1-b1b2faa57d9c", "type": "concept", "title": "Environmental antecedents: staffing, equipment, policies, supply, training, and management decisions"}], "description": "This subtopic explains how investigators identify contributing factors and root causes."}, {"id": "ec396612-ae48-4388-bb41-b1ba11bd94b4", "type": "subtopic", "title": "Recall and product withdrawal", "children": [{"id": "33aadf06-897d-45bc-b9d5-eb1b0d6b11db", "type": "concept", "title": "Recall classes/levels as defined by authority, notices, lot/date/product identification, and customer scope"}, {"id": "0f7575d4-883a-49e1-a7bb-4dde52ba974d", "type": "concept", "title": "Stop sale/use, quarantine, inventory count, site checks, downstream notification, and disposition"}, {"id": "71a3ee1e-75c3-42b6-8e53-b2e9f7756bc4", "type": "concept", "title": "Effectiveness checks, records, regulator/supplier communication, and recall drills"}], "description": "Students learn to locate, control, reconcile, and document affected product promptly."}, {"id": "b9e95453-a01b-417e-a777-ed8a863b638c", "type": "subtopic", "title": "Crisis communication and recovery", "children": [{"id": "af04a440-e0c5-4f9f-b0a0-009b31fd37a2", "type": "concept", "title": "Single information lead, approved messages, internal briefings, guest/customer notification, media/social monitoring, and multilingual access"}, {"id": "fdc74a18-2a21-401a-b295-4b21b200649e", "type": "concept", "title": "What is known, unknown, being done, and when updates will follow"}, {"id": "00aa0cdc-93df-4aa5-814d-a55de151db59", "type": "concept", "title": "Corrective-action plan, verification, reopening, support for affected people and staff, reputation recovery, and lessons learned"}], "description": "Students communicate facts, actions, and uncertainty while centering public health and affected people."}]}], "dbBacked": true}$fsafjson$::jsonb,
  true,
  false,
  'course',
  'public'
where not exists (
  select 1 from public.learning_paths where slug = 'food-safety-and-sanitation'
);

update public.learning_paths
set
  title = 'Food Safety and Sanitation',
  goal = 'Food Safety and Sanitation',
  summary = 'This course introduces the science, law, systems, and managerial practices used to prevent foodborne illness and protect food in hospitality operations. Students identify biological, chemical, physical, and allergen hazards; apply employee health and hygiene controls; manage time and temperature; protect food through purchasing, receiving, storage, preparation, cooking, cooling, holding, service, delivery, and catering; design cleaning, sanitation, pest, facility, and utility controls; build HACCP and active-managerial-control systems; interpret inspection findings; strengthen food-safety culture; and respond to complaints, outbreaks, recalls, and emergencies. Applied laboratories and case exercises prepare students for an accredited food protection manager examination while emphasizing that certification complements—not replaces—competent daily management.',
  data = $fsafjson${"slug": "food-safety-and-sanitation", "title": "Food Safety and Sanitation", "description": "This course introduces the science, law, systems, and managerial practices used to prevent foodborne illness and protect food in hospitality operations. Students identify biological, chemical, physical, and allergen hazards; apply employee health and hygiene controls; manage time and temperature; protect food through purchasing, receiving, storage, preparation, cooking, cooling, holding, service, delivery, and catering; design cleaning, sanitation, pest, facility, and utility controls; build HACCP and active-managerial-control systems; interpret inspection findings; strengthen food-safety culture; and respond to complaints, outbreaks, recalls, and emergencies. Applied laboratories and case exercises prepare students for an accredited food protection manager examination while emphasizing that certification complements—not replaces—competent daily management.", "topics": [{"id": "e48b3980-c170-49a8-9338-27972b8cfaf0", "type": "topic", "title": "Food Safety Foundations, Public Health, and Regulation", "description": "This section frames food safety as a public-health and management responsibility. Students learn how science, law, operations, and human behavior work together to prevent illness and protect guests, employees, and the business.", "children": [{"id": "5172ba2d-bdd0-4c8a-a620-37dbae9e6956", "type": "subtopic", "title": "Burden and pathways of foodborne illness", "children": [{"id": "b31e446c-ebe6-44c3-b362-ae47d23a3b11", "type": "concept", "title": "Foodborne infection, intoxication, toxin-mediated infection, injury, and long-term sequelae"}, {"id": "0769f073-171e-4278-8296-6f17c0527d5c", "type": "concept", "title": "Sporadic illness, clusters, outbreaks, endemic disease, and underreporting"}, {"id": "f614022a-c9f2-41c9-badd-6401ec733d05", "type": "concept", "title": "Higher-risk populations and institutional foodservice responsibilities"}], "description": "Students begin with why controls matter: foodborne disease can cause severe harm, disproportionately affect vulnerable populations, and damage trust and livelihoods."}, {"id": "69d6ef66-75d5-437d-b5d3-614995e8250b", "type": "subtopic", "title": "Farm-to-fork system and shared responsibility", "children": [{"id": "916be0d0-67e0-412a-a498-44277d8e706e", "type": "concept", "title": "Primary production, processing, distribution, retail, foodservice, delivery, and consumption"}, {"id": "96c2864f-b196-4763-a85a-ae8b73b69cb6", "type": "concept", "title": "Regulators, operators, certified managers, persons in charge, employees, suppliers, and guests"}, {"id": "91e5ace9-96bb-4417-93fa-193a51230682", "type": "concept", "title": "Prevention, detection, response, recovery, and continuous improvement"}], "description": "This subtopic shows that safety depends on linked controls from supplier through service and consumer handling."}, {"id": "991041bf-2c90-48ba-9612-c9d6b496d42e", "type": "subtopic", "title": "Regulatory framework and code literacy", "children": [{"id": "31494b70-b1fd-48bb-9b87-66be4aaada5d", "type": "concept", "title": "FDA Food Code as a U.S. model; state, local, tribal, territorial, and federal adoption"}, {"id": "355fae34-2da4-45ab-8972-abce7c23cda3", "type": "concept", "title": "Competent authorities and local requirements outside the United States"}, {"id": "a84659dc-ff94-43b9-ac87-51475974fc21", "type": "concept", "title": "Priority items, priority foundation items, core items, permits, variances, and enforcement"}], "description": "Students learn to find and interpret the rules actually adopted in their jurisdiction rather than assuming a model code is automatically law."}]}, {"id": "a724b0df-cb81-445f-afe7-cb8093200d37", "type": "topic", "title": "Biological Hazards, Pathogens, and Contamination", "description": "This section builds the microbiological foundation needed to understand why specific operational controls work. Students focus on hazard behavior and control—not memorizing disconnected organism lists.", "children": [{"id": "1ff84458-31bd-4ca2-b68d-7c87fe7f44f9", "type": "subtopic", "title": "Types of biological hazards", "children": [{"id": "2c6c0a26-a99b-4f05-a75a-a8e0c57931a2", "type": "concept", "title": "Bacteria, viruses, parasites, fungi, prions, and biological toxins"}, {"id": "d02f19ef-f3e0-4eb1-82c5-809df5198df7", "type": "concept", "title": "Spore-formers, toxin producers, acid tolerance, and environmental persistence"}, {"id": "510dbb7f-c86b-4207-8e6b-44274db9e07d", "type": "concept", "title": "Foodborne versus person-to-person and environmental transmission"}], "description": "Students distinguish organisms and agents by survival, growth, transmission, and control needs."}, {"id": "6324544b-d7af-48bf-9613-a353db930c9f", "type": "subtopic", "title": "Priority pathogens and food associations", "children": [{"id": "3fad4cf4-09d1-47f9-9c69-1c5444a20944", "type": "concept", "title": "Norovirus, Salmonella, Shiga toxin-producing E. coli, Campylobacter, Listeria monocytogenes, Clostridium perfringens, Clostridium botulinum, Bacillus cereus, Staphylococcus aureus, and hepatitis A"}, {"id": "c7eea06c-8863-4c00-ad9c-918cbe2eef3d", "type": "concept", "title": "Raw/undercooked animal foods, produce, ready-to-eat foods, rice and grains, seafood, and low-oxygen foods"}, {"id": "18457c6a-0100-4cae-a0c5-78c2ca78fdca", "type": "concept", "title": "Incubation, duration, dose, asymptomatic shedding, and vulnerable populations"}], "description": "This subtopic connects representative hazards to foods, symptoms, severity, and prevention while avoiding false certainty about a single source."}, {"id": "2ad5a4ae-5fda-4150-bbd5-616172328e2d", "type": "subtopic", "title": "Contamination routes and growth conditions", "children": [{"id": "054af8c2-cf28-410e-8b95-44fdfccd2b27", "type": "concept", "title": "Source contamination, hands, surfaces, utensils, droplets/aerosols, pests, water, soil, and waste"}, {"id": "e89cbdbd-3972-42f4-9113-6fef5e024d70", "type": "concept", "title": "Cross-contamination and environmental niches/biofilms"}, {"id": "549f7ae1-cffa-442a-ae58-7443ac48ee39", "type": "concept", "title": "Food, acidity, time, temperature, oxygen, and moisture as growth factors"}], "description": "Students map how hazards enter, move through, survive, and multiply in an operation."}]}, {"id": "f466b63f-e8ba-44bd-a55c-fdddc3e56b71", "type": "topic", "title": "Personal Hygiene, Employee Health, and Human Factors", "description": "Food handlers are essential control partners, not simply sources of risk. This section develops scientifically grounded hygiene, illness-reporting, and work-design practices that employees can realistically follow.", "children": [{"id": "b2c7dfb7-80c1-473c-90ab-9e68aaf2aefc", "type": "subtopic", "title": "Hand hygiene and hygienic practices", "children": [{"id": "6f7e5098-d760-4a8c-8ef9-01bfed47312a", "type": "concept", "title": "Handwashing steps, sinks, supplies, timing, drying, and monitoring"}, {"id": "d2a91d44-32eb-4ca8-b891-46a3d26bc148", "type": "concept", "title": "Bare-hand contact with ready-to-eat food; gloves and utensils"}, {"id": "d174ce93-1d6c-4e94-a86b-09b38722aa62", "type": "concept", "title": "Fingernails, jewelry, clothing, hair restraints, wounds, eating, drinking, and tobacco/vaping"}], "description": "Students learn when and how hygiene interrupts transmission and why gloves never replace correct handwashing."}, {"id": "c53f5460-887f-42c0-b70e-48f811266544", "type": "subtopic", "title": "Employee health program", "children": [{"id": "eb5b6394-7e63-499f-a23e-712cb6e6cf43", "type": "concept", "title": "Vomiting, diarrhea, jaundice, sore throat with fever, infected lesions, and jurisdiction-specific reportable conditions"}, {"id": "d3d9e5ba-497e-47cb-8e10-ee3067c360dc", "type": "concept", "title": "Conditional employees, food employees, person in charge, agreements, records, and return-to-work rules"}, {"id": "44ef12a0-60f9-48b4-83ae-d28b2275cfee", "type": "concept", "title": "Paid sick leave, fear of discipline, staffing pressure, language access, and non-retaliation"}], "description": "This subtopic connects symptoms, diagnoses, exposure, reporting, restriction, exclusion, clearance, and confidentiality."}, {"id": "e37d669e-d6bd-4ad8-b22e-74197e668beb", "type": "subtopic", "title": "Human factors and behavior", "children": [{"id": "c0765fba-3441-4d22-8468-768a23840099", "type": "concept", "title": "Workload, fatigue, heat, time pressure, staffing, equipment placement, and production targets"}, {"id": "089dd067-79fa-4dbb-bdf7-fae86a8895e5", "type": "concept", "title": "Norms, cues, feedback, supervision, incentives, and psychological safety"}, {"id": "7e6c49c1-e8ba-4064-b41a-c99ffe9aacc6", "type": "concept", "title": "Observation, coaching, error-proofing, and just-culture responses"}], "description": "Students examine why knowledge alone does not produce safe practice and how systems can make the safe action easier."}]}, {"id": "07df9024-8796-4787-be48-7a19c1074d11", "type": "topic", "title": "Allergens, Chemical Hazards, and Physical Hazards", "description": "Not all food-safety hazards are microorganisms. This section prepares students to control allergens, toxic chemicals, natural toxins, and foreign objects through procurement, labeling, separation, communication, and incident readiness.", "children": [{"id": "3436b361-a95a-41b3-92f8-b87047edd181", "type": "subtopic", "title": "Food-allergen management", "children": [{"id": "ca98819c-5359-4fad-8da1-eeab9fb7545d", "type": "concept", "title": "Jurisdiction-specific major allergens; sesame in the current U.S. framework"}, {"id": "e22ef47d-d308-4309-8fa3-ddeaeb4a5acf", "type": "concept", "title": "Ingredient and label review, recipe control, substitutions, supplier changes, and rework"}, {"id": "63b148e9-c76c-4665-b49c-f1e820af340d", "type": "concept", "title": "Order communication, dedicated tools/areas where needed, cleaning validation, plating, delivery, and emergency response"}], "description": "Students learn to prevent allergen cross-contact and communicate accurately from supplier label to guest service."}, {"id": "072d3db1-f956-4a2b-bced-faebb9733082", "type": "subtopic", "title": "Chemical hazards and toxic substances", "children": [{"id": "7c3d9985-9fd9-4cdf-8556-66d2c1302c5a", "type": "concept", "title": "Cleaning and sanitizing chemicals, pesticides, lubricants, metals, additives, and migration from equipment/packaging"}, {"id": "00dbed01-7007-40eb-99eb-2f1c35d1f828", "type": "concept", "title": "Natural toxins, histamine/scombrotoxin, ciguatoxin, mycotoxins, and toxic mushrooms/plants"}, {"id": "7261c796-ee16-455f-aae4-378c5a4ff29b", "type": "concept", "title": "Original containers, labels, safety data sheets, storage, concentration, rinsing, and approved use"}], "description": "This subtopic covers chemicals that may be naturally present, intentionally used, or accidentally introduced."}, {"id": "717cb781-8079-4797-85c8-fb0e5b3878a2", "type": "subtopic", "title": "Physical hazards and foreign material", "children": [{"id": "f21ff270-780f-47d9-a200-8f2e16ed5f08", "type": "concept", "title": "Glass, hard plastic, metal, wood, stones, jewelry, bone, pits, packaging, and personal items"}, {"id": "6946ff6b-0eb8-4ad6-92cd-80665e62950b", "type": "concept", "title": "Preventive maintenance, protective covers, receiving inspection, breakage procedures, and product holds"}, {"id": "1567712c-5615-4151-b8f2-a34964d54e13", "type": "concept", "title": "Customer complaint assessment, documentation, disposition, and escalation"}], "description": "Students learn to identify sources and design prevention and response controls."}]}, {"id": "61f6bfc5-8e1d-4f28-b516-df6bd8d25ec7", "type": "topic", "title": "Time and Temperature Control", "description": "Time and temperature are among the most powerful foodservice controls. Students learn the science, measurement, monitoring, and corrective actions needed across the entire flow of food.", "children": [{"id": "725b44ca-fb05-4746-b233-c56cb9ff03c8", "type": "subtopic", "title": "Temperature danger and pathogen behavior", "children": [{"id": "57f6d533-b449-4a5e-9b35-f4348c9fdaad", "type": "concept", "title": "Time/temperature control for safety food and jurisdictional definitions"}, {"id": "b396a1cb-19a6-4a8b-9543-bec30b0c0ee2", "type": "concept", "title": "Growth curves, lag time, cumulative exposure, and heat resistance"}, {"id": "69d069e2-3a25-4e6a-87fc-567218be54c0", "type": "concept", "title": "Toxin hazards that cooking may not reverse"}], "description": "Students connect growth, survival, spore germination, and toxin formation to operational decisions."}, {"id": "ef512d99-db06-40cc-959c-436705a96929", "type": "subtopic", "title": "Thermometers and measurement systems", "children": [{"id": "190d4b3c-3e68-4859-8de1-2f5c932bdfe6", "type": "concept", "title": "Bimetallic stem, thermistor/thermocouple, infrared, probe types, data loggers, and equipment gauges"}, {"id": "51b3a1fb-7f9c-430a-ac50-0f0fdb311e4b", "type": "concept", "title": "Calibration/verification methods, accuracy, response time, measurement location, and uncertainty"}, {"id": "6c311f54-49f4-4cfd-a615-eb0b4c5ea3e9", "type": "concept", "title": "Cleaning/sanitizing probes, records, alarms, and corrective action"}], "description": "This subtopic develops confidence in selecting, placing, calibrating, using, cleaning, and interpreting instruments."}, {"id": "712983c5-a548-42dc-abbd-6ca58593b39b", "type": "subtopic", "title": "Cold and hot control through the process", "children": [{"id": "dc7e9a88-2648-4ce7-b20c-97e40d71f810", "type": "concept", "title": "Receiving, storage, thawing, preparation, cooking, hot holding, cold holding, cooling, reheating, and service"}, {"id": "3e704aed-61ef-497b-979f-47afd198e84d", "type": "concept", "title": "Time as a public-health control, labeling, discard times, written procedures, and monitoring"}, {"id": "e7d7cf57-d7d8-4076-b6a0-d761b7b82cf4", "type": "concept", "title": "Batch size, shallow pans, ice baths, blast chilling, heat transfer, equipment loading, and verification"}], "description": "Students apply the currently adopted code limits and approved procedures rather than relying on memory alone."}]}, {"id": "20e9ebd8-df2b-4742-9c94-e89a905a4738", "type": "topic", "title": "Approved Sources, Receiving, Storage, and Traceability", "description": "Food safety begins before the delivery arrives. This section teaches students to qualify suppliers, verify receiving conditions, maintain storage controls, and preserve records needed to trace and isolate product.", "children": [{"id": "2996f7c3-29d6-403a-851e-e594df3f6ce6", "type": "subtopic", "title": "Approved suppliers and specifications", "children": [{"id": "6601448d-533d-40bc-972a-8e1f99de035b", "type": "concept", "title": "Licensing/inspection status, third-party assurances, recall capability, allergen and ingredient data, and cold-chain controls"}, {"id": "1e40f7ba-638a-4953-a46f-6f486250cc26", "type": "concept", "title": "Product specifications, substitutions, rejection criteria, and supplier performance"}, {"id": "a56e5b3a-be63-4d21-84a3-df4ed92c0980", "type": "concept", "title": "Shellstock, game, wild mushrooms, donated food, and other jurisdiction-sensitive sources"}], "description": "Students learn to source from lawful, capable suppliers and define safety requirements in purchasing documents."}, {"id": "407649ab-79c2-49bb-8603-728c4c8208b6", "type": "subtopic", "title": "Receiving and acceptance", "children": [{"id": "0db5d7de-80eb-40e8-8af2-bd3f3ca3bbf9", "type": "concept", "title": "Vehicle and package condition, seals, temperatures, dates, labels, documentation, pests, and evidence of thaw/refreeze"}, {"id": "3f47511b-c43f-4511-978c-befce5cc9411", "type": "concept", "title": "Sampling plans, calibrated instruments, rejection, segregation, and incident escalation"}, {"id": "d2da9048-dfb2-4ec3-a42e-c3e2308d7ad8", "type": "concept", "title": "Receiving schedule, staffing, dock hygiene, and rapid put-away"}], "description": "This subtopic turns the loading dock into an active control point."}, {"id": "2e1149de-0124-472c-acac-185da8a3e85f", "type": "subtopic", "title": "Storage and stock rotation", "children": [{"id": "cdbfaaf0-aaf6-43c8-87ab-ab5f56a044be", "type": "concept", "title": "Separation of raw and ready-to-eat foods; covered, labeled, and elevated storage"}, {"id": "76ee1fdf-d10e-47bb-a54f-3706020b1862", "type": "concept", "title": "Date marking, first-in/first-out or first-expired/first-out, shelf life, and discard"}, {"id": "28adcaf8-28d0-4823-99cd-d5ab468de073", "type": "concept", "title": "Temperature mapping, overcrowding, air flow, power loss, and inventory checks"}], "description": "Students organize dry, refrigerated, frozen, chemical, and protected storage to prevent contamination and loss of control."}, {"id": "5de72de1-2734-422c-af60-fdbe5ea56dd9", "type": "subtopic", "title": "Traceability and recall readiness", "children": [{"id": "0c29a663-ba63-4831-ac9e-8abd25120de7", "type": "concept", "title": "One-step-forward/one-step-back concepts and internal lot/location tracking"}, {"id": "4e445861-07f8-4c66-afda-0389b65f65f9", "type": "concept", "title": "Shellstock tags, invoices, production records, labels, and digital systems"}, {"id": "0a42fbc9-0ebc-4ac7-bf60-9146d9a2eb4e", "type": "concept", "title": "Product hold, inventory reconciliation, recall checks, disposition, and effectiveness verification"}], "description": "Students maintain source, lot, date, quantity, and disposition information so affected food can be found quickly."}]}, {"id": "6643a077-44b0-45e9-a583-025d0997b5a7", "type": "topic", "title": "Safe Preparation, Cooking, Cooling, Reheating, Holding, and Service", "description": "This section integrates controls across kitchen production. Students learn to prevent cross-contamination, achieve validated lethality, limit growth, and protect food through service and leftovers.", "children": [{"id": "d6a82c7d-efb6-416a-8d6a-c47d49020421", "type": "subtopic", "title": "Preparation and cross-contamination prevention", "children": [{"id": "73a8f8c0-7ef6-4e5f-96a1-a65f8d272cca", "type": "concept", "title": "Raw-to-ready-to-eat separation, color coding, dedicated equipment, and preparation scheduling"}, {"id": "ae04d103-1037-453e-93dc-6112ac9b49e8", "type": "concept", "title": "Thawing methods, washing produce, pooled eggs, batters/breading, and handling ready-to-eat foods"}, {"id": "f7f421a6-3cef-4f26-9392-d7164c0ce793", "type": "concept", "title": "Small batches, exposure time, return to control, and corrective action"}], "description": "Students design workflow, zoning, sequencing, utensils, and cleaning around the separation of hazards."}, {"id": "0853f977-976e-456e-b270-f5f107f2a3a8", "type": "subtopic", "title": "Cooking and process controls", "children": [{"id": "68277515-fa42-46ed-a292-58eb67208f4d", "type": "concept", "title": "Minimum internal cooking parameters and approved alternatives"}, {"id": "3ed388ab-f57d-4b0d-ba04-f8dc0d0f3ded", "type": "concept", "title": "Whole-muscle, ground, injected/tenderized, poultry, eggs, seafood, plant foods, microwave, and roasts"}, {"id": "206200f3-7466-4dae-8bbc-7e1ef810fcbf", "type": "concept", "title": "Probe placement, multiple measurements, carryover, consumer advisories, and recordkeeping"}], "description": "This subtopic connects food type and process to the required, measured endpoint in the adopted code."}, {"id": "60624a13-c597-45ef-af34-c430105dd6a0", "type": "subtopic", "title": "Cooling, reheating, and holding", "children": [{"id": "63aa4418-1c71-4e3f-92bf-07b547e942b2", "type": "concept", "title": "Two-stage cooling concepts, rapid methods, uncovered/loosely covered cooling as allowed, and verification"}, {"id": "1518f577-8f4b-4f26-819e-563a1f63d649", "type": "concept", "title": "Reheating for hot holding versus immediate service"}, {"id": "d34332f1-364a-46c1-be31-ab568576d223", "type": "concept", "title": "Hot/cold holding equipment, stirring, lids, batch replacement, and corrective action"}], "description": "Students learn why large batches fail and how equipment, container geometry, and monitoring change outcomes."}, {"id": "4c2743c5-b367-4ec1-abd9-a76a7a3b42e4", "type": "subtopic", "title": "Service, displays, and leftovers", "children": [{"id": "c4f846f7-e55e-4601-90d1-8af837f18d49", "type": "concept", "title": "Self-service, buffets, sneeze guards, utensils, consumer contamination, and replenishment"}, {"id": "3167224a-5498-433c-b380-9dc7321b88e4", "type": "concept", "title": "Return/re-service restrictions, takeout packaging, delivery handoff, and guest instructions"}, {"id": "4492547a-784d-4713-b630-4704eb552afe", "type": "concept", "title": "Leftover decisions, donation, cooling, labeling, transport, and approved disposition"}], "description": "This subtopic protects food at the last operational mile."}]}, {"id": "fc44fed3-f8be-4650-9e9e-1765e31f40ce", "type": "topic", "title": "Cleaning, Sanitizing, and Environmental Hygiene", "description": "Cleaning removes soil; sanitizing reduces microorganisms to safe levels. Students learn to design, execute, verify, and improve sanitation programs appropriate to food-contact and non-food-contact environments.", "children": [{"id": "b27c61f3-339e-4688-ad10-df0f31a3faa1", "type": "subtopic", "title": "Cleaning chemistry and mechanics", "children": [{"id": "95b18000-e2cb-40e5-b743-310b295812ca", "type": "concept", "title": "Fats, proteins, carbohydrates, minerals, biofilms, and allergen residues"}, {"id": "f641557e-59f1-4aa8-afca-06af26d3398c", "type": "concept", "title": "Detergents, degreasers, acids, alkalis, enzymes, and compatibility"}, {"id": "5ae7984e-ff9d-4064-9de1-83ea9a6d933c", "type": "concept", "title": "Pre-clean, wash, rinse, inspect, sanitize where required, and air-dry"}], "description": "Students connect soil type, surface, water, time, temperature, chemistry, and mechanical action to effective cleaning."}, {"id": "ec7b9c4e-56a4-4708-aa70-b2e044df8915", "type": "subtopic", "title": "Sanitization methods and control", "children": [{"id": "977e7b1b-9940-4ed8-8d59-a63aafd7fd72", "type": "concept", "title": "Concentration, contact time, temperature, pH, water hardness, and organic load"}, {"id": "fb4ee515-1f36-4f9b-854b-51cd0f6b6408", "type": "concept", "title": "Test kits, automated dispensers, three-compartment sinks, dishmachines, and manual methods"}, {"id": "e046f0d5-df08-4f12-b6f2-5779dcc1021d", "type": "concept", "title": "Too weak, too strong, mixing hazards, residues, and corrective action"}], "description": "This subtopic develops correct use of heat and approved chemical sanitizers."}, {"id": "15b8baf3-fd2a-421d-b01b-7f9e3a9f39a0", "type": "subtopic", "title": "Master sanitation program and verification", "children": [{"id": "ed3e09da-e22a-4da4-adfb-a2c9e505360a", "type": "concept", "title": "Food-contact surfaces, in-use utensils, ice machines, beverage systems, slicers, drains, hoods, coolers, and high-touch points"}, {"id": "f2a654df-1b43-4f14-9ea8-4640c1bfcaee", "type": "concept", "title": "Clean-in-place, disassembly, lockout/tagout interfaces, and sanitation standard operating procedures"}, {"id": "a149c786-e222-4125-976d-f1caf4dcb510", "type": "concept", "title": "Visual inspection, records, ATP/protein/allergen tools, microbiological testing where appropriate, trends, and corrective action"}], "description": "Students create a risk-based schedule that assigns what, how, when, who, and how performance is verified."}]}, {"id": "06985a12-7264-46d4-b130-2015803d0318", "type": "topic", "title": "Facilities, Equipment, Water, Waste, and Pest Management", "description": "Safe food depends on the built environment and utilities. This section teaches students to evaluate hygienic design, maintain potable water and waste systems, and use integrated pest management.", "children": [{"id": "d26e3e0a-4d0d-4711-bcd7-43fff17867f0", "type": "subtopic", "title": "Hygienic facility and equipment design", "children": [{"id": "022302ba-8f5a-4d9b-bca8-6a544adff25d", "type": "concept", "title": "Smooth, durable, nonabsorbent, corrosion-resistant, accessible, and cleanable surfaces"}, {"id": "2b165e49-251e-43f7-8734-9b75f59a9388", "type": "concept", "title": "Equipment certification, installation, spacing, sealing, drainage, ventilation, lighting, and hand sinks"}, {"id": "7d7298d2-d9c9-418b-b619-952920bb9121", "type": "concept", "title": "Raw/ready-to-eat zones, employee areas, storage, warewashing, refuse, and traffic patterns"}], "description": "Students identify design features that support cleaning, separation, maintenance, and safe flow."}, {"id": "a1aa7c6d-0862-451c-9eac-2c72277fc15a", "type": "subtopic", "title": "Water, ice, plumbing, sewage, and waste", "children": [{"id": "3877fde0-a2ba-4f2e-a47e-4df6b7f49afc", "type": "concept", "title": "Potable water, ice as food, hoses, cross-connections, air gaps, backflow devices, and grease systems"}, {"id": "e332390c-9728-450b-8fae-1fab2c261d5b", "type": "concept", "title": "Sewage backups, drain overflows, condensation, leaks, and standing water"}, {"id": "1903fe1c-0eb3-4e8c-86fe-6705d300a28c", "type": "concept", "title": "Waste segregation, covered containers, used oil, rendering, composting, and refuse area hygiene"}], "description": "This subtopic emphasizes safe sources, backflow prevention, drainage, and rapid response to utility failures."}, {"id": "39115434-e731-4b76-9595-cfdd6c096501", "type": "subtopic", "title": "Integrated pest management", "children": [{"id": "374f319d-b686-49cb-9a00-0377b17de1b1", "type": "concept", "title": "Entry points, harborage, food/water sources, doors, screens, seals, and landscaping"}, {"id": "041b6f7f-bba6-443a-9099-097395ed3a9a", "type": "concept", "title": "Monitoring devices, pest evidence, maps, trend logs, and contractor reports"}, {"id": "8c3704f8-d9db-40fe-9709-d2f1a804366a", "type": "concept", "title": "Approved pesticide use, preparation protection, dead-pest removal, root-cause correction, and verification"}], "description": "Students focus on exclusion, sanitation, monitoring, and targeted control rather than routine pesticide dependence."}, {"id": "82f0d03f-3424-41da-ab2f-faf545c0a0c4", "type": "subtopic", "title": "Preventive maintenance and utilities resilience", "children": [{"id": "9f2c555b-96a1-405c-8c50-b09878f9ae80", "type": "concept", "title": "Gaskets, thermometers, refrigeration, hot water, dishmachines, drains, and food-contact surface integrity"}, {"id": "d43b1f7a-42b4-4798-a60f-5cb03ddca6e0", "type": "concept", "title": "Work orders, temporary controls, out-of-service decisions, and post-repair cleaning"}, {"id": "8bcddd8a-0c33-477c-b4d4-1cc8e26f8988", "type": "concept", "title": "Power, water, gas, refrigeration, and ventilation interruption plans"}], "description": "Students connect equipment condition and contingency planning to food-safety control."}]}, {"id": "0b7ec4ca-cceb-4e59-b598-ec40ebad1625", "type": "topic", "title": "HACCP, Preventive Controls, and Active Managerial Control", "description": "This section turns hazard knowledge into a preventive management system. Students learn to analyze processes, establish controls, verify performance, and take corrective action before unsafe food reaches a guest.", "children": [{"id": "b55b1175-5b48-49b6-b933-e158b5bc2212", "type": "subtopic", "title": "Prerequisite programs and process mapping", "children": [{"id": "fc01d0be-7f4e-4103-a36a-2816fd0993aa", "type": "concept", "title": "Approved sources, hygiene, sanitation, maintenance, pest control, training, allergen, and supplier programs"}, {"id": "a221930b-7118-4f46-b6e7-b86cc5f9fe65", "type": "concept", "title": "Product description, intended use, consumers, flow diagram, on-site confirmation, and process categories"}, {"id": "db656796-6d5c-46ba-bd7b-d6b08657da72", "type": "concept", "title": "Operational prerequisite programs and jurisdictional terminology"}], "description": "Students first establish dependable basic conditions and a truthful picture of how food flows."}, {"id": "f7fc174e-0999-4454-9e30-b0579bea5c30", "type": "subtopic", "title": "Seven HACCP principles", "children": [{"id": "d359823a-cdae-44d4-83f4-fc4ea974dbfa", "type": "concept", "title": "Hazard analysis and control-measure selection"}, {"id": "72711732-6a54-4730-a37f-20e027b4e791", "type": "concept", "title": "Critical control points, validated critical limits, monitoring, corrective action, verification, and records"}, {"id": "d0c614d2-c95c-4aa4-a461-6a00bb8d359a", "type": "concept", "title": "Validation versus verification; deviations, disposition, and reassessment"}], "description": "This subtopic teaches a disciplined method for significant hazard control."}, {"id": "e474b76f-7774-447e-b1fd-29abd1d2ecf9", "type": "subtopic", "title": "Active managerial control", "children": [{"id": "9537d14d-359d-406b-9f26-e41b736c5585", "type": "concept", "title": "Demonstration of knowledge, employee health, approved sources, cooking, holding, contaminated equipment, and other risk factors"}, {"id": "019d8630-d4c3-41b0-83e2-9d9555a4a307", "type": "concept", "title": "Daily checks, manager observations, exception reporting, and ownership"}, {"id": "ff0216f2-5084-4c7e-b4a5-f85ed634b816", "type": "concept", "title": "Trend analysis, focused interventions, accountability, and continuous improvement"}], "description": "Students learn to manage the common risk factors every shift through policies, training, monitoring, and corrective action."}, {"id": "b84a6e73-1e0c-4bbb-80fc-f14a62e40dd5", "type": "subtopic", "title": "Special processes and variances", "children": [{"id": "e5c9a374-4cb1-4562-81d1-29a6a5d26f4a", "type": "concept", "title": "Variance triggers and HACCP plan requirements"}, {"id": "a735332e-f916-4278-9495-8ce0f51e3980", "type": "concept", "title": "Reduced-oxygen packaging, sous vide, cook-chill, smoking for preservation, curing, custom processing, live molluscan shellfish tanks, sprouting, and acidification"}, {"id": "44431d24-fe1c-438a-acfb-c4228414308e", "type": "concept", "title": "Scientific support, validation, labeling, shelf life, monitoring, records, and regulator consultation"}], "description": "This subtopic makes clear that reduced-oxygen packaging, curing, acidification, sprouting, and other processes require specialized controls and often regulatory approval."}]}, {"id": "cab95990-0e69-4224-91c4-72c08f26623d", "type": "topic", "title": "Inspection, Compliance, Documentation, and Corrective Action", "description": "Regulatory inspections are snapshots; food safety must be managed continuously. Students learn to prepare through daily control, communicate professionally, interpret findings, and close the loop on violations.", "children": [{"id": "a54a16f0-f5c8-4177-8b43-90c251c77ab2", "type": "subtopic", "title": "Risk-based inspection and regulatory interaction", "children": [{"id": "0e3856f4-d5d5-40db-a4da-b73529c8eb02", "type": "concept", "title": "Preoperational and operational observations, temperatures, interviews, records, sampling, and embargo/hold authorities"}, {"id": "4327c2d8-5095-4a29-8db4-5c3be617d09e", "type": "concept", "title": "Priority classifications, compliance timeframes, follow-up, enforcement, appeal, and due process"}, {"id": "a2157646-89c3-49cf-979f-15ff70e77cb3", "type": "concept", "title": "Cooperation, truthful records, employee support, note taking, and escalation to leadership/counsel"}], "description": "Students understand inspection purpose, methods, evidence, and professional responsibilities."}, {"id": "174aa235-cffb-42e9-862f-a46f5386eabe", "type": "subtopic", "title": "Records and evidence", "children": [{"id": "895dabed-61e8-4e90-bde7-48e17d3a4aa2", "type": "concept", "title": "Receiving, temperature, cooling, sanitizer, employee health, training, cleaning, pest, maintenance, allergen, and corrective-action records"}, {"id": "4ae0fc75-181d-43e4-aab2-e64d5e905e9c", "type": "concept", "title": "Legibility, timestamps, instrument/lot identification, signatures, electronic controls, retention, and privacy"}, {"id": "5e0fb597-0da9-4a75-8123-ece2d91f5d4e", "type": "concept", "title": "Review by exception, falsification risk, record availability, and trend analysis"}], "description": "This subtopic focuses on concise, accurate documentation that supports control rather than paperwork for its own sake."}, {"id": "985d9da8-e3a3-4933-b601-0939ab683dcc", "type": "subtopic", "title": "Corrective and preventive action", "children": [{"id": "970aa245-96f6-4ca8-aa09-48a0213bbebb", "type": "concept", "title": "Immediate control, affected-food assessment, hold/discard/rework only when approved, and documentation"}, {"id": "9517a1f3-e737-40ff-a8ea-7eca3d8a9f76", "type": "concept", "title": "Five whys, fishbone, process mapping, contributing factors, and environmental antecedents"}, {"id": "8b4d5046-bb89-47c2-830a-9d8f16deca03", "type": "concept", "title": "Owner, due date, preventive change, effectiveness check, recurrence monitoring, and closure"}], "description": "Students move beyond fixing the immediate symptom to address system causes and verify effectiveness."}]}, {"id": "ac175b01-2988-4009-8901-19f71e80454b", "type": "topic", "title": "Food Safety Management Systems, Culture, and Training", "description": "World-class operations treat food safety as a managed organizational value. This section develops leadership practices that align policies, resources, behavior, data, and accountability.", "children": [{"id": "cb61e78e-cf94-4f1e-900c-e77aa6b27b87", "type": "subtopic", "title": "Food-safety policy and governance", "children": [{"id": "4670d81a-b520-44dd-ab76-ed13decacad0", "type": "concept", "title": "Policy, scope, legal register, objectives, roles, and management review"}, {"id": "3e9d512b-00e7-4c0a-8c3a-14af1de8dd21", "type": "concept", "title": "Person-in-charge coverage, certified food protection manager requirements, delegation, and succession"}, {"id": "4fc99d29-7ee1-4971-aaa3-6cdbfb948e2b", "type": "concept", "title": "Supplier standards, internal audits, incident review, and executive accountability"}], "description": "Students connect public-health commitments to roles, resources, metrics, and escalation."}, {"id": "098a0806-0ffe-4649-ad6a-c64c81787d80", "type": "subtopic", "title": "Food-safety culture", "children": [{"id": "a3b8f7b3-1c83-4e49-8d1a-831d3e8551fa", "type": "concept", "title": "Leadership credibility, communication, resources, risk awareness, employee voice, and consistency"}, {"id": "6162e2b7-f5c7-4137-8d48-62e912da0cab", "type": "concept", "title": "Just culture, stop-work authority, reporting without retaliation, and learning from near misses"}, {"id": "3700e688-9297-4062-87fc-0a8dc5100cfe", "type": "concept", "title": "Climate surveys, observations, turnover, sick-work behavior, and leading indicators"}], "description": "This subtopic examines what people believe is truly prioritized when production pressure conflicts with safety."}, {"id": "0e25c865-e725-4fd5-ba78-76d88403faed", "type": "subtopic", "title": "Training and competency", "children": [{"id": "b337af0c-1e04-4a15-a9ba-419551a4cdd7", "type": "concept", "title": "Onboarding, task training, refreshers, language/literacy access, demonstrations, and job aids"}, {"id": "4b3f8e48-9626-4acd-a50f-2c43f12fdd9f", "type": "concept", "title": "Explain–demonstrate–practice–observe–coach–verify cycle"}, {"id": "e65775ec-3bb9-456d-bdb3-e06746c72e04", "type": "concept", "title": "Knowledge tests, skills observation, retraining triggers, trainer qualification, and records"}], "description": "Students design role-specific learning that results in observable performance."}, {"id": "f60f55fe-4e25-4f1b-baef-8fcb74344731", "type": "subtopic", "title": "Certification and professional development", "children": [{"id": "62d047d1-5e5d-4710-96d4-68f6cdc0cfff", "type": "concept", "title": "Certification content domains and exam strategy"}, {"id": "7b7b9fa8-c330-4cc4-9270-4c6952d4f469", "type": "concept", "title": "Jurisdictional accreditation/recognition and renewal requirements"}, {"id": "ba6da822-2a29-40ec-8d8f-f1a62b90ee2f", "type": "concept", "title": "Continuing education, code updates, emerging hazards, and communities of practice"}], "description": "Students prepare for manager certification while understanding that passing an exam is only one element of competence."}]}, {"id": "656c3108-4b49-4b7d-b655-f8e78cc8296f", "type": "topic", "title": "Special Operations: Catering, Buffets, Delivery, Mobile, and High-Risk Service", "description": "Hospitality operations often move food away from the controlled kitchen. This section applies core principles to changing locations, delayed service, transportation, temporary utilities, and vulnerable populations.", "children": [{"id": "40b538cb-dfb3-45ba-8c65-325bdd384016", "type": "subtopic", "title": "Catering and off-site service", "children": [{"id": "deac5d09-9a63-43b9-8c3b-acf9d58bcd8f", "type": "concept", "title": "Approved prep site, transport containers, vehicle hygiene, route/time, temperature monitoring, and contingency"}, {"id": "d46d58b9-c9c3-40ff-b457-0f020181ccd5", "type": "concept", "title": "Temporary handwashing, warewashing, protected service, power, water, waste, and pest controls"}, {"id": "a4c9216a-dbd9-4b8c-8115-b82f56ab1fef", "type": "concept", "title": "Venue responsibility matrix, pre-event inspection, leftovers, and post-event reconciliation"}], "description": "Students plan the cold/hot chain, sanitation, water, transport, setup, service, and return/disposition before departure."}, {"id": "39bbf396-073d-46e1-b115-72b306a214bf", "type": "subtopic", "title": "Buffets, banquets, self-service, and room service", "children": [{"id": "3b450a3d-21d1-4eea-97a6-55e08a03e63f", "type": "concept", "title": "Small-batch replenishment, holding equipment, shields, utensils, labels, staff monitoring, and replacement rules"}, {"id": "29b4bdbf-de6c-4132-9432-49b086404f92", "type": "concept", "title": "Banquet plating lines, carts, elevators, remote pantries, room service, and tray retrieval"}, {"id": "9a6d325e-9a9d-4f33-b47c-a6b3db02ffae", "type": "concept", "title": "Allergen communication, vulnerable guests, and time control"}], "description": "This subtopic addresses high volume, long service periods, guest interaction, and batch management."}, {"id": "3b2edd81-db73-4ee3-b00e-0aa07b08f5c7", "type": "subtopic", "title": "Delivery, takeout, mobile, temporary, and outdoor foodservice", "children": [{"id": "14016461-ceb7-4882-bc34-4a80a0da757e", "type": "concept", "title": "Packaging suitability, separation, seals, labels, pickup shelving, driver handoff, and consumer instructions"}, {"id": "0bb62a10-5dda-4419-87f1-22bf8b4c705f", "type": "concept", "title": "Food trucks, temporary events, farmers markets, pop-ups, ghost kitchens, and shared kitchens"}, {"id": "d9b65588-7519-4f24-bfd6-65323915d108", "type": "concept", "title": "Weather, dust, pests, water/ice, refrigeration, generators, waste, permits, and closure thresholds"}], "description": "Students design for packaging, tamper evidence, last-mile delay, weather, limited utilities, and changing volume."}, {"id": "b1d68777-7865-4df6-afe2-4b3b4f0e33ca", "type": "subtopic", "title": "Highly susceptible populations and institutional settings", "children": [{"id": "84d1d3fe-cf4c-4585-ba5a-2a90db9a708e", "type": "concept", "title": "Hospitals, long-term care, childcare, and other jurisdiction-defined settings"}, {"id": "4a782a39-4ae8-439a-bd92-e51cdb396f54", "type": "concept", "title": "Restricted foods and processes, pasteurization, service controls, and employee health"}, {"id": "d3deff5b-eff0-4fdd-a2b3-3f59fbfaef6d", "type": "concept", "title": "Menu approval, clinical coordination, outbreak sensitivity, and documentation"}], "description": "Students apply enhanced restrictions and policies where consequences are greater."}]}, {"id": "6779e73b-31dd-4395-9a05-05c7670edf49", "type": "topic", "title": "Food Defense, Food Fraud, and Emergency Preparedness", "description": "Food safety programs must also address intentional harm, economically motivated adulteration, and disruptions to utilities or supply. Students learn proportionate prevention and response without creating fear or false certainty.", "children": [{"id": "e1b3b389-252e-4868-8e3c-e2b5e8d21af6", "type": "subtopic", "title": "Food defense", "children": [{"id": "f6e13dca-4744-4866-9021-13aa12bfeaf3", "type": "concept", "title": "Intentional adulteration, sabotage, threats, suspicious behavior, and insider risk"}, {"id": "38b0e8a8-df27-4cdd-9774-c7c1d4a9d48c", "type": "concept", "title": "Access control, visitor/vendor management, chemical and key control, seals, cameras where lawful, and reporting"}, {"id": "b265e7e5-af16-4da8-8968-c8352fb88d6e", "type": "concept", "title": "Threat assessment, law-enforcement/public-health coordination, evidence preservation, and employee safety"}], "description": "Students identify vulnerable points and practical protective measures appropriate to the operation."}, {"id": "b571bde1-d960-49e1-9e04-2efe9b24dcd3", "type": "subtopic", "title": "Food fraud and supply integrity", "children": [{"id": "8963fe8e-3767-4a45-bbb9-07e4f2029818", "type": "concept", "title": "Substitution, dilution, concealment, counterfeiting, mislabeling, and gray markets"}, {"id": "2d311773-b6cf-4451-981e-6bad9018580e", "type": "concept", "title": "Vulnerable commodities, supplier verification, specifications, testing/assurance, and traceability"}, {"id": "2f2cb9db-8bc7-4fb3-b19f-059564e6052f", "type": "concept", "title": "Escalation, product hold, legal review, and customer communication"}], "description": "This subtopic connects authenticity and economic deception to potential safety hazards and trust."}, {"id": "e298b992-7cb0-4bad-bd0d-e438a6b9f29d", "type": "subtopic", "title": "Emergency action planning", "children": [{"id": "5e57d3d9-332d-41a0-99d6-8a2ceec5bf25", "type": "concept", "title": "Power outage, refrigeration failure, water interruption/boil advisory, sewage backup, fire, flood, severe weather, contamination, and cyber outage"}, {"id": "8323df3b-744b-4036-a946-8573d130f216", "type": "concept", "title": "Assess–notify–isolate–monitor–document–recover sequence"}, {"id": "386b6ba0-d706-44e1-81c2-1d67ac21fde0", "type": "concept", "title": "Alternative water/ice, temporary menus, backup power, relocation, disposal, regulator approval, and reopening verification"}], "description": "Students create decision trees for events that may require restricted operations or closure."}]}, {"id": "7f31fa4a-e870-4ee6-9001-78388a55fbd1", "type": "topic", "title": "Outbreak Investigation, Recalls, Crisis Communication, and Recovery", "description": "The final section prepares future managers to recognize signals, protect people, cooperate with authorities, preserve evidence, communicate responsibly, and correct system failures.", "children": [{"id": "6ea04c95-6840-4d07-b4fc-f27864fb69a2", "type": "subtopic", "title": "Illness complaint and outbreak response", "children": [{"id": "10de32f7-b9ff-41d9-aa4d-620c385919ec", "type": "concept", "title": "Complaint intake: contact, foods, meal date/time, symptoms/onset, others ill, medical care, and reporter details"}, {"id": "fd6a91c1-18ac-4a34-a6c6-a0097de923c6", "type": "concept", "title": "Immediate manager notification, employee health review, implicated-food hold, records preservation, and regulator contact"}, {"id": "749e5155-1b20-4b45-a4ba-c15542bc3a8d", "type": "concept", "title": "Confidentiality, no retaliation, no speculative conclusions, and coordination with public health"}], "description": "Students learn to treat complaints seriously without diagnosing or admitting unsupported causation."}, {"id": "50eb39a9-2f9e-4ad8-bc7d-7692bee411bb", "type": "subtopic", "title": "Environmental assessment and epidemiologic support", "children": [{"id": "b74991c0-81c8-4284-92c9-e8b1411e1a53", "type": "concept", "title": "Case definition, interviews, line lists, descriptive epidemiology, traceback, sampling, and laboratory evidence"}, {"id": "01520963-6915-4a79-8c8e-e558bfe548bd", "type": "concept", "title": "Food-specific and system-level contributing factors"}, {"id": "8dedbb00-7154-45e0-86b1-b1b2faa57d9c", "type": "concept", "title": "Environmental antecedents: staffing, equipment, policies, supply, training, and management decisions"}], "description": "This subtopic explains how investigators identify contributing factors and root causes."}, {"id": "ec396612-ae48-4388-bb41-b1ba11bd94b4", "type": "subtopic", "title": "Recall and product withdrawal", "children": [{"id": "33aadf06-897d-45bc-b9d5-eb1b0d6b11db", "type": "concept", "title": "Recall classes/levels as defined by authority, notices, lot/date/product identification, and customer scope"}, {"id": "0f7575d4-883a-49e1-a7bb-4dde52ba974d", "type": "concept", "title": "Stop sale/use, quarantine, inventory count, site checks, downstream notification, and disposition"}, {"id": "71a3ee1e-75c3-42b6-8e53-b2e9f7756bc4", "type": "concept", "title": "Effectiveness checks, records, regulator/supplier communication, and recall drills"}], "description": "Students learn to locate, control, reconcile, and document affected product promptly."}, {"id": "b9e95453-a01b-417e-a777-ed8a863b638c", "type": "subtopic", "title": "Crisis communication and recovery", "children": [{"id": "af04a440-e0c5-4f9f-b0a0-009b31fd37a2", "type": "concept", "title": "Single information lead, approved messages, internal briefings, guest/customer notification, media/social monitoring, and multilingual access"}, {"id": "fdc74a18-2a21-401a-b295-4b21b200649e", "type": "concept", "title": "What is known, unknown, being done, and when updates will follow"}, {"id": "00aa0cdc-93df-4aa5-814d-a55de151db59", "type": "concept", "title": "Corrective-action plan, verification, reopening, support for affected people and staff, reputation recovery, and lessons learned"}], "description": "Students communicate facts, actions, and uncertainty while centering public health and affected people."}]}], "dbBacked": true}$fsafjson$::jsonb,
