insert into public.curated_courses (id, slug, title, description)
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('e48b3980-c170-49a8-9338-27972b8cfaf0', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', null, 'topic'::public.curated_course_node_type, 'Food Safety Foundations, Public Health, and Regulation', 'This section frames food safety as a public-health and management responsibility. Students learn how science, law, operations, and human behavior work together to prevent illness and protect guests, employees, and the business.', 0),
  ('5172ba2d-bdd0-4c8a-a620-37dbae9e6956', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', 'e48b3980-c170-49a8-9338-27972b8cfaf0', 'subtopic'::public.curated_course_node_type, 'Burden and pathways of foodborne illness', 'Students begin with why controls matter: foodborne disease can cause severe harm, disproportionately affect vulnerable populations, and damage trust and livelihoods.', 0),
  ('b31e446c-ebe6-44c3-b362-ae47d23a3b11', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', '5172ba2d-bdd0-4c8a-a620-37dbae9e6956', 'concept'::public.curated_course_node_type, 'Foodborne infection, intoxication, toxin-mediated infection, injury, and long-term sequelae', null, 0),
  ('0769f073-171e-4278-8296-6f17c0527d5c', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', '5172ba2d-bdd0-4c8a-a620-37dbae9e6956', 'concept'::public.curated_course_node_type, 'Sporadic illness, clusters, outbreaks, endemic disease, and underreporting', null, 1),
  ('f614022a-c9f2-41c9-badd-6401ec733d05', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', '5172ba2d-bdd0-4c8a-a620-37dbae9e6956', 'concept'::public.curated_course_node_type, 'Higher-risk populations and institutional foodservice responsibilities', null, 2),
  ('69d6ef66-75d5-437d-b5d3-614995e8250b', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', 'e48b3980-c170-49a8-9338-27972b8cfaf0', 'subtopic'::public.curated_course_node_type, 'Farm-to-fork system and shared responsibility', 'This subtopic shows that safety depends on linked controls from supplier through service and consumer handling.', 1),
  ('916be0d0-67e0-412a-a498-44277d8e706e', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', '69d6ef66-75d5-437d-b5d3-614995e8250b', 'concept'::public.curated_course_node_type, 'Primary production, processing, distribution, retail, foodservice, delivery, and consumption', null, 0),
  ('96c2864f-b196-4763-a85a-ae8b73b69cb6', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', '69d6ef66-75d5-437d-b5d3-614995e8250b', 'concept'::public.curated_course_node_type, 'Regulators, operators, certified managers, persons in charge, employees, suppliers, and guests', null, 1),
  ('91e5ace9-96bb-4417-93fa-193a51230682', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', '69d6ef66-75d5-437d-b5d3-614995e8250b', 'concept'::public.curated_course_node_type, 'Prevention, detection, response, recovery, and continuous improvement', null, 2),
  ('991041bf-2c90-48ba-9612-c9d6b496d42e', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', 'e48b3980-c170-49a8-9338-27972b8cfaf0', 'subtopic'::public.curated_course_node_type, 'Regulatory framework and code literacy', 'Students learn to find and interpret the rules actually adopted in their jurisdiction rather than assuming a model code is automatically law.', 2),
  ('31494b70-b1fd-48bb-9b87-66be4aaada5d', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', '991041bf-2c90-48ba-9612-c9d6b496d42e', 'concept'::public.curated_course_node_type, 'FDA Food Code as a U.S. model; state, local, tribal, territorial, and federal adoption', null, 0),
  ('355fae34-2da4-45ab-8972-abce7c23cda3', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', '991041bf-2c90-48ba-9612-c9d6b496d42e', 'concept'::public.curated_course_node_type, 'Competent authorities and local requirements outside the United States', null, 1),
  ('a84659dc-ff94-43b9-ac87-51475974fc21', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', '991041bf-2c90-48ba-9612-c9d6b496d42e', 'concept'::public.curated_course_node_type, 'Priority items, priority foundation items, core items, permits, variances, and enforcement', null, 2),
  ('a724b0df-cb81-445f-afe7-cb8093200d37', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', null, 'topic'::public.curated_course_node_type, 'Biological Hazards, Pathogens, and Contamination', 'This section builds the microbiological foundation needed to understand why specific operational controls work. Students focus on hazard behavior and control—not memorizing disconnected organism lists.', 1),
  ('1ff84458-31bd-4ca2-b68d-7c87fe7f44f9', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', 'a724b0df-cb81-445f-afe7-cb8093200d37', 'subtopic'::public.curated_course_node_type, 'Types of biological hazards', 'Students distinguish organisms and agents by survival, growth, transmission, and control needs.', 0),
  ('2c6c0a26-a99b-4f05-a75a-a8e0c57931a2', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', '1ff84458-31bd-4ca2-b68d-7c87fe7f44f9', 'concept'::public.curated_course_node_type, 'Bacteria, viruses, parasites, fungi, prions, and biological toxins', null, 0),
  ('d02f19ef-f3e0-4eb1-82c5-809df5198df7', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', '1ff84458-31bd-4ca2-b68d-7c87fe7f44f9', 'concept'::public.curated_course_node_type, 'Spore-formers, toxin producers, acid tolerance, and environmental persistence', null, 1),
  ('510dbb7f-c86b-4207-8e6b-44274db9e07d', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', '1ff84458-31bd-4ca2-b68d-7c87fe7f44f9', 'concept'::public.curated_course_node_type, 'Foodborne versus person-to-person and environmental transmission', null, 2),
  ('6324544b-d7af-48bf-9613-a353db930c9f', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', 'a724b0df-cb81-445f-afe7-cb8093200d37', 'subtopic'::public.curated_course_node_type, 'Priority pathogens and food associations', 'This subtopic connects representative hazards to foods, symptoms, severity, and prevention while avoiding false certainty about a single source.', 1),
  ('3fad4cf4-09d1-47f9-9c69-1c5444a20944', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', '6324544b-d7af-48bf-9613-a353db930c9f', 'concept'::public.curated_course_node_type, 'Norovirus, Salmonella, Shiga toxin-producing E. coli, Campylobacter, Listeria monocytogenes, Clostridium perfringens, Clostridium botulinum, Bacillus cereus, Staphylococcus aureus, and hepatitis A', null, 0),
  ('c7eea06c-8863-4c00-ad9c-918cbe2eef3d', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', '6324544b-d7af-48bf-9613-a353db930c9f', 'concept'::public.curated_course_node_type, 'Raw/undercooked animal foods, produce, ready-to-eat foods, rice and grains, seafood, and low-oxygen foods', null, 1),
  ('18457c6a-0100-4cae-a0c5-78c2ca78fdca', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', '6324544b-d7af-48bf-9613-a353db930c9f', 'concept'::public.curated_course_node_type, 'Incubation, duration, dose, asymptomatic shedding, and vulnerable populations', null, 2),
  ('2ad5a4ae-5fda-4150-bbd5-616172328e2d', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', 'a724b0df-cb81-445f-afe7-cb8093200d37', 'subtopic'::public.curated_course_node_type, 'Contamination routes and growth conditions', 'Students map how hazards enter, move through, survive, and multiply in an operation.', 2),
  ('054af8c2-cf28-410e-8b95-44fdfccd2b27', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', '2ad5a4ae-5fda-4150-bbd5-616172328e2d', 'concept'::public.curated_course_node_type, 'Source contamination, hands, surfaces, utensils, droplets/aerosols, pests, water, soil, and waste', null, 0),
  ('e89cbdbd-3972-42f4-9113-6fef5e024d70', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', '2ad5a4ae-5fda-4150-bbd5-616172328e2d', 'concept'::public.curated_course_node_type, 'Cross-contamination and environmental niches/biofilms', null, 1),
  ('549f7ae1-cffa-442a-ae58-7443ac48ee39', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', '2ad5a4ae-5fda-4150-bbd5-616172328e2d', 'concept'::public.curated_course_node_type, 'Food, acidity, time, temperature, oxygen, and moisture as growth factors', null, 2),
  ('f466b63f-e8ba-44bd-a55c-fdddc3e56b71', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', null, 'topic'::public.curated_course_node_type, 'Personal Hygiene, Employee Health, and Human Factors', 'Food handlers are essential control partners, not simply sources of risk. This section develops scientifically grounded hygiene, illness-reporting, and work-design practices that employees can realistically follow.', 2),
  ('b2c7dfb7-80c1-473c-90ab-9e68aaf2aefc', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', 'f466b63f-e8ba-44bd-a55c-fdddc3e56b71', 'subtopic'::public.curated_course_node_type, 'Hand hygiene and hygienic practices', 'Students learn when and how hygiene interrupts transmission and why gloves never replace correct handwashing.', 0),
  ('6f7e5098-d760-4a8c-8ef9-01bfed47312a', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', 'b2c7dfb7-80c1-473c-90ab-9e68aaf2aefc', 'concept'::public.curated_course_node_type, 'Handwashing steps, sinks, supplies, timing, drying, and monitoring', null, 0),
  ('d2a91d44-32eb-4ca8-b891-46a3d26bc148', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', 'b2c7dfb7-80c1-473c-90ab-9e68aaf2aefc', 'concept'::public.curated_course_node_type, 'Bare-hand contact with ready-to-eat food; gloves and utensils', null, 1),
  ('d174ce93-1d6c-4e94-a86b-09b38722aa62', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', 'b2c7dfb7-80c1-473c-90ab-9e68aaf2aefc', 'concept'::public.curated_course_node_type, 'Fingernails, jewelry, clothing, hair restraints, wounds, eating, drinking, and tobacco/vaping', null, 2),
  ('c53f5460-887f-42c0-b70e-48f811266544', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', 'f466b63f-e8ba-44bd-a55c-fdddc3e56b71', 'subtopic'::public.curated_course_node_type, 'Employee health program', 'This subtopic connects symptoms, diagnoses, exposure, reporting, restriction, exclusion, clearance, and confidentiality.', 1),
  ('eb5b6394-7e63-499f-a23e-712cb6e6cf43', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', 'c53f5460-887f-42c0-b70e-48f811266544', 'concept'::public.curated_course_node_type, 'Vomiting, diarrhea, jaundice, sore throat with fever, infected lesions, and jurisdiction-specific reportable conditions', null, 0),
  ('d3d9e5ba-497e-47cb-8e10-ee3067c360dc', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', 'c53f5460-887f-42c0-b70e-48f811266544', 'concept'::public.curated_course_node_type, 'Conditional employees, food employees, person in charge, agreements, records, and return-to-work rules', null, 1),
  ('44ef12a0-60f9-48b4-83ae-d28b2275cfee', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', 'c53f5460-887f-42c0-b70e-48f811266544', 'concept'::public.curated_course_node_type, 'Paid sick leave, fear of discipline, staffing pressure, language access, and non-retaliation', null, 2),
  ('e37d669e-d6bd-4ad8-b22e-74197e668beb', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', 'f466b63f-e8ba-44bd-a55c-fdddc3e56b71', 'subtopic'::public.curated_course_node_type, 'Human factors and behavior', 'Students examine why knowledge alone does not produce safe practice and how systems can make the safe action easier.', 2),
  ('c0765fba-3441-4d22-8468-768a23840099', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', 'e37d669e-d6bd-4ad8-b22e-74197e668beb', 'concept'::public.curated_course_node_type, 'Workload, fatigue, heat, time pressure, staffing, equipment placement, and production targets', null, 0),
  ('089dd067-79fa-4dbb-bdf7-fae86a8895e5', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', 'e37d669e-d6bd-4ad8-b22e-74197e668beb', 'concept'::public.curated_course_node_type, 'Norms, cues, feedback, supervision, incentives, and psychological safety', null, 1),
  ('7e6c49c1-e8ba-4064-b41a-c99ffe9aacc6', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', 'e37d669e-d6bd-4ad8-b22e-74197e668beb', 'concept'::public.curated_course_node_type, 'Observation, coaching, error-proofing, and just-culture responses', null, 2),
  ('07df9024-8796-4787-be48-7a19c1074d11', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', null, 'topic'::public.curated_course_node_type, 'Allergens, Chemical Hazards, and Physical Hazards', 'Not all food-safety hazards are microorganisms. This section prepares students to control allergens, toxic chemicals, natural toxins, and foreign objects through procurement, labeling, separation, communication, and incident readiness.', 3);
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('3436b361-a95a-41b3-92f8-b87047edd181', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', '07df9024-8796-4787-be48-7a19c1074d11', 'subtopic'::public.curated_course_node_type, 'Food-allergen management', 'Students learn to prevent allergen cross-contact and communicate accurately from supplier label to guest service.', 0),
  ('ca98819c-5359-4fad-8da1-eeab9fb7545d', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', '3436b361-a95a-41b3-92f8-b87047edd181', 'concept'::public.curated_course_node_type, 'Jurisdiction-specific major allergens; sesame in the current U.S. framework', null, 0),
  ('e22ef47d-d308-4309-8fa3-ddeaeb4a5acf', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', '3436b361-a95a-41b3-92f8-b87047edd181', 'concept'::public.curated_course_node_type, 'Ingredient and label review, recipe control, substitutions, supplier changes, and rework', null, 1),
  ('63b148e9-c76c-4665-b49c-f1e820af340d', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', '3436b361-a95a-41b3-92f8-b87047edd181', 'concept'::public.curated_course_node_type, 'Order communication, dedicated tools/areas where needed, cleaning validation, plating, delivery, and emergency response', null, 2),
  ('072d3db1-f956-4a2b-bced-faebb9733082', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', '07df9024-8796-4787-be48-7a19c1074d11', 'subtopic'::public.curated_course_node_type, 'Chemical hazards and toxic substances', 'This subtopic covers chemicals that may be naturally present, intentionally used, or accidentally introduced.', 1),
  ('7c3d9985-9fd9-4cdf-8556-66d2c1302c5a', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', '072d3db1-f956-4a2b-bced-faebb9733082', 'concept'::public.curated_course_node_type, 'Cleaning and sanitizing chemicals, pesticides, lubricants, metals, additives, and migration from equipment/packaging', null, 0),
  ('00dbed01-7007-40eb-99eb-2f1c35d1f828', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', '072d3db1-f956-4a2b-bced-faebb9733082', 'concept'::public.curated_course_node_type, 'Natural toxins, histamine/scombrotoxin, ciguatoxin, mycotoxins, and toxic mushrooms/plants', null, 1),
  ('7261c796-ee16-455f-aae4-378c5a4ff29b', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', '072d3db1-f956-4a2b-bced-faebb9733082', 'concept'::public.curated_course_node_type, 'Original containers, labels, safety data sheets, storage, concentration, rinsing, and approved use', null, 2),
  ('717cb781-8079-4797-85c8-fb0e5b3878a2', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', '07df9024-8796-4787-be48-7a19c1074d11', 'subtopic'::public.curated_course_node_type, 'Physical hazards and foreign material', 'Students learn to identify sources and design prevention and response controls.', 2),
  ('f21ff270-780f-47d9-a200-8f2e16ed5f08', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', '717cb781-8079-4797-85c8-fb0e5b3878a2', 'concept'::public.curated_course_node_type, 'Glass, hard plastic, metal, wood, stones, jewelry, bone, pits, packaging, and personal items', null, 0),
  ('6946ff6b-0eb8-4ad6-92cd-80665e62950b', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', '717cb781-8079-4797-85c8-fb0e5b3878a2', 'concept'::public.curated_course_node_type, 'Preventive maintenance, protective covers, receiving inspection, breakage procedures, and product holds', null, 1),
  ('1567712c-5615-4151-b8f2-a34964d54e13', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', '717cb781-8079-4797-85c8-fb0e5b3878a2', 'concept'::public.curated_course_node_type, 'Customer complaint assessment, documentation, disposition, and escalation', null, 2),
  ('61f6bfc5-8e1d-4f28-b516-df6bd8d25ec7', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', null, 'topic'::public.curated_course_node_type, 'Time and Temperature Control', 'Time and temperature are among the most powerful foodservice controls. Students learn the science, measurement, monitoring, and corrective actions needed across the entire flow of food.', 4),
  ('725b44ca-fb05-4746-b233-c56cb9ff03c8', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', '61f6bfc5-8e1d-4f28-b516-df6bd8d25ec7', 'subtopic'::public.curated_course_node_type, 'Temperature danger and pathogen behavior', 'Students connect growth, survival, spore germination, and toxin formation to operational decisions.', 0),
  ('57f6d533-b449-4a5e-9b35-f4348c9fdaad', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', '725b44ca-fb05-4746-b233-c56cb9ff03c8', 'concept'::public.curated_course_node_type, 'Time/temperature control for safety food and jurisdictional definitions', null, 0),
  ('b396a1cb-19a6-4a8b-9543-bec30b0c0ee2', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', '725b44ca-fb05-4746-b233-c56cb9ff03c8', 'concept'::public.curated_course_node_type, 'Growth curves, lag time, cumulative exposure, and heat resistance', null, 1),
  ('69d069e2-3a25-4e6a-87fc-567218be54c0', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', '725b44ca-fb05-4746-b233-c56cb9ff03c8', 'concept'::public.curated_course_node_type, 'Toxin hazards that cooking may not reverse', null, 2),
  ('ef512d99-db06-40cc-959c-436705a96929', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', '61f6bfc5-8e1d-4f28-b516-df6bd8d25ec7', 'subtopic'::public.curated_course_node_type, 'Thermometers and measurement systems', 'This subtopic develops confidence in selecting, placing, calibrating, using, cleaning, and interpreting instruments.', 1),
  ('190d4b3c-3e68-4859-8de1-2f5c932bdfe6', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', 'ef512d99-db06-40cc-959c-436705a96929', 'concept'::public.curated_course_node_type, 'Bimetallic stem, thermistor/thermocouple, infrared, probe types, data loggers, and equipment gauges', null, 0),
  ('51b3a1fb-7f9c-430a-ac50-0f0fdb311e4b', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', 'ef512d99-db06-40cc-959c-436705a96929', 'concept'::public.curated_course_node_type, 'Calibration/verification methods, accuracy, response time, measurement location, and uncertainty', null, 1),
  ('6c311f54-49f4-4cfd-a615-eb0b4c5ea3e9', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', 'ef512d99-db06-40cc-959c-436705a96929', 'concept'::public.curated_course_node_type, 'Cleaning/sanitizing probes, records, alarms, and corrective action', null, 2),
  ('712983c5-a548-42dc-abbd-6ca58593b39b', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', '61f6bfc5-8e1d-4f28-b516-df6bd8d25ec7', 'subtopic'::public.curated_course_node_type, 'Cold and hot control through the process', 'Students apply the currently adopted code limits and approved procedures rather than relying on memory alone.', 2),
  ('dc7e9a88-2648-4ce7-b20c-97e40d71f810', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', '712983c5-a548-42dc-abbd-6ca58593b39b', 'concept'::public.curated_course_node_type, 'Receiving, storage, thawing, preparation, cooking, hot holding, cold holding, cooling, reheating, and service', null, 0),
  ('3e704aed-61ef-497b-979f-47afd198e84d', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', '712983c5-a548-42dc-abbd-6ca58593b39b', 'concept'::public.curated_course_node_type, 'Time as a public-health control, labeling, discard times, written procedures, and monitoring', null, 1),
  ('e7d7cf57-d7d8-4076-b6a0-d761b7b82cf4', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', '712983c5-a548-42dc-abbd-6ca58593b39b', 'concept'::public.curated_course_node_type, 'Batch size, shallow pans, ice baths, blast chilling, heat transfer, equipment loading, and verification', null, 2),
  ('20e9ebd8-df2b-4742-9c94-e89a905a4738', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', null, 'topic'::public.curated_course_node_type, 'Approved Sources, Receiving, Storage, and Traceability', 'Food safety begins before the delivery arrives. This section teaches students to qualify suppliers, verify receiving conditions, maintain storage controls, and preserve records needed to trace and isolate product.', 5),
  ('2996f7c3-29d6-403a-851e-e594df3f6ce6', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', '20e9ebd8-df2b-4742-9c94-e89a905a4738', 'subtopic'::public.curated_course_node_type, 'Approved suppliers and specifications', 'Students learn to source from lawful, capable suppliers and define safety requirements in purchasing documents.', 0),
  ('6601448d-533d-40bc-972a-8e1f99de035b', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', '2996f7c3-29d6-403a-851e-e594df3f6ce6', 'concept'::public.curated_course_node_type, 'Licensing/inspection status, third-party assurances, recall capability, allergen and ingredient data, and cold-chain controls', null, 0),
  ('1e40f7ba-638a-4953-a46f-6f486250cc26', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', '2996f7c3-29d6-403a-851e-e594df3f6ce6', 'concept'::public.curated_course_node_type, 'Product specifications, substitutions, rejection criteria, and supplier performance', null, 1),
  ('a56e5b3a-be63-4d21-84a3-df4ed92c0980', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', '2996f7c3-29d6-403a-851e-e594df3f6ce6', 'concept'::public.curated_course_node_type, 'Shellstock, game, wild mushrooms, donated food, and other jurisdiction-sensitive sources', null, 2),
  ('407649ab-79c2-49bb-8603-728c4c8208b6', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', '20e9ebd8-df2b-4742-9c94-e89a905a4738', 'subtopic'::public.curated_course_node_type, 'Receiving and acceptance', 'This subtopic turns the loading dock into an active control point.', 1),
  ('0db5d7de-80eb-40e8-8af2-bd3f3ca3bbf9', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', '407649ab-79c2-49bb-8603-728c4c8208b6', 'concept'::public.curated_course_node_type, 'Vehicle and package condition, seals, temperatures, dates, labels, documentation, pests, and evidence of thaw/refreeze', null, 0),
  ('3f47511b-c43f-4511-978c-befce5cc9411', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', '407649ab-79c2-49bb-8603-728c4c8208b6', 'concept'::public.curated_course_node_type, 'Sampling plans, calibrated instruments, rejection, segregation, and incident escalation', null, 1),
  ('d2da9048-dfb2-4ec3-a42e-c3e2308d7ad8', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', '407649ab-79c2-49bb-8603-728c4c8208b6', 'concept'::public.curated_course_node_type, 'Receiving schedule, staffing, dock hygiene, and rapid put-away', null, 2),
  ('2e1149de-0124-472c-acac-185da8a3e85f', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', '20e9ebd8-df2b-4742-9c94-e89a905a4738', 'subtopic'::public.curated_course_node_type, 'Storage and stock rotation', 'Students organize dry, refrigerated, frozen, chemical, and protected storage to prevent contamination and loss of control.', 2),
  ('cdbfaaf0-aaf6-43c8-87ab-ab5f56a044be', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', '2e1149de-0124-472c-acac-185da8a3e85f', 'concept'::public.curated_course_node_type, 'Separation of raw and ready-to-eat foods; covered, labeled, and elevated storage', null, 0),
  ('76ee1fdf-d10e-47bb-a54f-3706020b1862', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', '2e1149de-0124-472c-acac-185da8a3e85f', 'concept'::public.curated_course_node_type, 'Date marking, first-in/first-out or first-expired/first-out, shelf life, and discard', null, 1),
  ('28adcaf8-28d0-4823-99cd-d5ab468de073', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', '2e1149de-0124-472c-acac-185da8a3e85f', 'concept'::public.curated_course_node_type, 'Temperature mapping, overcrowding, air flow, power loss, and inventory checks', null, 2),
  ('5de72de1-2734-422c-af60-fdbe5ea56dd9', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', '20e9ebd8-df2b-4742-9c94-e89a905a4738', 'subtopic'::public.curated_course_node_type, 'Traceability and recall readiness', 'Students maintain source, lot, date, quantity, and disposition information so affected food can be found quickly.', 3),
  ('0c29a663-ba63-4831-ac9e-8abd25120de7', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', '5de72de1-2734-422c-af60-fdbe5ea56dd9', 'concept'::public.curated_course_node_type, 'One-step-forward/one-step-back concepts and internal lot/location tracking', null, 0);
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('4e445861-07f8-4c66-afda-0389b65f65f9', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', '5de72de1-2734-422c-af60-fdbe5ea56dd9', 'concept'::public.curated_course_node_type, 'Shellstock tags, invoices, production records, labels, and digital systems', null, 1),
  ('0a42fbc9-0ebc-4ac7-bf60-9146d9a2eb4e', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', '5de72de1-2734-422c-af60-fdbe5ea56dd9', 'concept'::public.curated_course_node_type, 'Product hold, inventory reconciliation, recall checks, disposition, and effectiveness verification', null, 2),
  ('6643a077-44b0-45e9-a583-025d0997b5a7', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', null, 'topic'::public.curated_course_node_type, 'Safe Preparation, Cooking, Cooling, Reheating, Holding, and Service', 'This section integrates controls across kitchen production. Students learn to prevent cross-contamination, achieve validated lethality, limit growth, and protect food through service and leftovers.', 6),
  ('d6a82c7d-efb6-416a-8d6a-c47d49020421', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', '6643a077-44b0-45e9-a583-025d0997b5a7', 'subtopic'::public.curated_course_node_type, 'Preparation and cross-contamination prevention', 'Students design workflow, zoning, sequencing, utensils, and cleaning around the separation of hazards.', 0),
  ('73a8f8c0-7ef6-4e5f-96a1-a65f8d272cca', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', 'd6a82c7d-efb6-416a-8d6a-c47d49020421', 'concept'::public.curated_course_node_type, 'Raw-to-ready-to-eat separation, color coding, dedicated equipment, and preparation scheduling', null, 0),
  ('ae04d103-1037-453e-93dc-6112ac9b49e8', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', 'd6a82c7d-efb6-416a-8d6a-c47d49020421', 'concept'::public.curated_course_node_type, 'Thawing methods, washing produce, pooled eggs, batters/breading, and handling ready-to-eat foods', null, 1),
  ('f7f421a6-3cef-4f26-9392-d7164c0ce793', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', 'd6a82c7d-efb6-416a-8d6a-c47d49020421', 'concept'::public.curated_course_node_type, 'Small batches, exposure time, return to control, and corrective action', null, 2),
  ('0853f977-976e-456e-b270-f5f107f2a3a8', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', '6643a077-44b0-45e9-a583-025d0997b5a7', 'subtopic'::public.curated_course_node_type, 'Cooking and process controls', 'This subtopic connects food type and process to the required, measured endpoint in the adopted code.', 1),
  ('68277515-fa42-46ed-a292-58eb67208f4d', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', '0853f977-976e-456e-b270-f5f107f2a3a8', 'concept'::public.curated_course_node_type, 'Minimum internal cooking parameters and approved alternatives', null, 0),
  ('3ed388ab-f57d-4b0d-ba04-f8dc0d0f3ded', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', '0853f977-976e-456e-b270-f5f107f2a3a8', 'concept'::public.curated_course_node_type, 'Whole-muscle, ground, injected/tenderized, poultry, eggs, seafood, plant foods, microwave, and roasts', null, 1),
  ('206200f3-7466-4dae-8bbc-7e1ef810fcbf', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', '0853f977-976e-456e-b270-f5f107f2a3a8', 'concept'::public.curated_course_node_type, 'Probe placement, multiple measurements, carryover, consumer advisories, and recordkeeping', null, 2),
  ('60624a13-c597-45ef-af34-c430105dd6a0', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', '6643a077-44b0-45e9-a583-025d0997b5a7', 'subtopic'::public.curated_course_node_type, 'Cooling, reheating, and holding', 'Students learn why large batches fail and how equipment, container geometry, and monitoring change outcomes.', 2),
  ('63aa4418-1c71-4e3f-92bf-07b547e942b2', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', '60624a13-c597-45ef-af34-c430105dd6a0', 'concept'::public.curated_course_node_type, 'Two-stage cooling concepts, rapid methods, uncovered/loosely covered cooling as allowed, and verification', null, 0),
  ('1518f577-8f4b-4f26-819e-563a1f63d649', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', '60624a13-c597-45ef-af34-c430105dd6a0', 'concept'::public.curated_course_node_type, 'Reheating for hot holding versus immediate service', null, 1),
  ('d34332f1-364a-46c1-be31-ab568576d223', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', '60624a13-c597-45ef-af34-c430105dd6a0', 'concept'::public.curated_course_node_type, 'Hot/cold holding equipment, stirring, lids, batch replacement, and corrective action', null, 2),
  ('4c2743c5-b367-4ec1-abd9-a76a7a3b42e4', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', '6643a077-44b0-45e9-a583-025d0997b5a7', 'subtopic'::public.curated_course_node_type, 'Service, displays, and leftovers', 'This subtopic protects food at the last operational mile.', 3),
  ('c4f846f7-e55e-4601-90d1-8af837f18d49', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', '4c2743c5-b367-4ec1-abd9-a76a7a3b42e4', 'concept'::public.curated_course_node_type, 'Self-service, buffets, sneeze guards, utensils, consumer contamination, and replenishment', null, 0),
  ('3167224a-5498-433c-b380-9dc7321b88e4', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', '4c2743c5-b367-4ec1-abd9-a76a7a3b42e4', 'concept'::public.curated_course_node_type, 'Return/re-service restrictions, takeout packaging, delivery handoff, and guest instructions', null, 1),
  ('4492547a-784d-4713-b630-4704eb552afe', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', '4c2743c5-b367-4ec1-abd9-a76a7a3b42e4', 'concept'::public.curated_course_node_type, 'Leftover decisions, donation, cooling, labeling, transport, and approved disposition', null, 2),
  ('fc44fed3-f8be-4650-9e9e-1765e31f40ce', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', null, 'topic'::public.curated_course_node_type, 'Cleaning, Sanitizing, and Environmental Hygiene', 'Cleaning removes soil; sanitizing reduces microorganisms to safe levels. Students learn to design, execute, verify, and improve sanitation programs appropriate to food-contact and non-food-contact environments.', 7),
  ('b27c61f3-339e-4688-ad10-df0f31a3faa1', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', 'fc44fed3-f8be-4650-9e9e-1765e31f40ce', 'subtopic'::public.curated_course_node_type, 'Cleaning chemistry and mechanics', 'Students connect soil type, surface, water, time, temperature, chemistry, and mechanical action to effective cleaning.', 0),
  ('95b18000-e2cb-40e5-b743-310b295812ca', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', 'b27c61f3-339e-4688-ad10-df0f31a3faa1', 'concept'::public.curated_course_node_type, 'Fats, proteins, carbohydrates, minerals, biofilms, and allergen residues', null, 0),
  ('f641557e-59f1-4aa8-afca-06af26d3398c', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', 'b27c61f3-339e-4688-ad10-df0f31a3faa1', 'concept'::public.curated_course_node_type, 'Detergents, degreasers, acids, alkalis, enzymes, and compatibility', null, 1),
  ('5ae7984e-ff9d-4064-9de1-83ea9a6d933c', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', 'b27c61f3-339e-4688-ad10-df0f31a3faa1', 'concept'::public.curated_course_node_type, 'Pre-clean, wash, rinse, inspect, sanitize where required, and air-dry', null, 2),
  ('ec7b9c4e-56a4-4708-aa70-b2e044df8915', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', 'fc44fed3-f8be-4650-9e9e-1765e31f40ce', 'subtopic'::public.curated_course_node_type, 'Sanitization methods and control', 'This subtopic develops correct use of heat and approved chemical sanitizers.', 1),
  ('977e7b1b-9940-4ed8-8d59-a63aafd7fd72', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', 'ec7b9c4e-56a4-4708-aa70-b2e044df8915', 'concept'::public.curated_course_node_type, 'Concentration, contact time, temperature, pH, water hardness, and organic load', null, 0),
  ('fb4ee515-1f36-4f9b-854b-51cd0f6b6408', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', 'ec7b9c4e-56a4-4708-aa70-b2e044df8915', 'concept'::public.curated_course_node_type, 'Test kits, automated dispensers, three-compartment sinks, dishmachines, and manual methods', null, 1),
  ('e046f0d5-df08-4f12-b6f2-5779dcc1021d', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', 'ec7b9c4e-56a4-4708-aa70-b2e044df8915', 'concept'::public.curated_course_node_type, 'Too weak, too strong, mixing hazards, residues, and corrective action', null, 2),
  ('15b8baf3-fd2a-421d-b01b-7f9e3a9f39a0', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', 'fc44fed3-f8be-4650-9e9e-1765e31f40ce', 'subtopic'::public.curated_course_node_type, 'Master sanitation program and verification', 'Students create a risk-based schedule that assigns what, how, when, who, and how performance is verified.', 2),
  ('ed3e09da-e22a-4da4-adfb-a2c9e505360a', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', '15b8baf3-fd2a-421d-b01b-7f9e3a9f39a0', 'concept'::public.curated_course_node_type, 'Food-contact surfaces, in-use utensils, ice machines, beverage systems, slicers, drains, hoods, coolers, and high-touch points', null, 0),
  ('f2a654df-1b43-4f14-9ea8-4640c1bfcaee', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', '15b8baf3-fd2a-421d-b01b-7f9e3a9f39a0', 'concept'::public.curated_course_node_type, 'Clean-in-place, disassembly, lockout/tagout interfaces, and sanitation standard operating procedures', null, 1),
  ('a149c786-e222-4125-976d-f1caf4dcb510', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', '15b8baf3-fd2a-421d-b01b-7f9e3a9f39a0', 'concept'::public.curated_course_node_type, 'Visual inspection, records, ATP/protein/allergen tools, microbiological testing where appropriate, trends, and corrective action', null, 2),
  ('06985a12-7264-46d4-b130-2015803d0318', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', null, 'topic'::public.curated_course_node_type, 'Facilities, Equipment, Water, Waste, and Pest Management', 'Safe food depends on the built environment and utilities. This section teaches students to evaluate hygienic design, maintain potable water and waste systems, and use integrated pest management.', 8),
  ('d26e3e0a-4d0d-4711-bcd7-43fff17867f0', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', '06985a12-7264-46d4-b130-2015803d0318', 'subtopic'::public.curated_course_node_type, 'Hygienic facility and equipment design', 'Students identify design features that support cleaning, separation, maintenance, and safe flow.', 0),
  ('022302ba-8f5a-4d9b-bca8-6a544adff25d', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', 'd26e3e0a-4d0d-4711-bcd7-43fff17867f0', 'concept'::public.curated_course_node_type, 'Smooth, durable, nonabsorbent, corrosion-resistant, accessible, and cleanable surfaces', null, 0),
  ('2b165e49-251e-43f7-8734-9b75f59a9388', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', 'd26e3e0a-4d0d-4711-bcd7-43fff17867f0', 'concept'::public.curated_course_node_type, 'Equipment certification, installation, spacing, sealing, drainage, ventilation, lighting, and hand sinks', null, 1),
  ('7d7298d2-d9c9-418b-b619-952920bb9121', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', 'd26e3e0a-4d0d-4711-bcd7-43fff17867f0', 'concept'::public.curated_course_node_type, 'Raw/ready-to-eat zones, employee areas, storage, warewashing, refuse, and traffic patterns', null, 2),
  ('a1aa7c6d-0862-451c-9eac-2c72277fc15a', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', '06985a12-7264-46d4-b130-2015803d0318', 'subtopic'::public.curated_course_node_type, 'Water, ice, plumbing, sewage, and waste', 'This subtopic emphasizes safe sources, backflow prevention, drainage, and rapid response to utility failures.', 1),
  ('3877fde0-a2ba-4f2e-a47e-4df6b7f49afc', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', 'a1aa7c6d-0862-451c-9eac-2c72277fc15a', 'concept'::public.curated_course_node_type, 'Potable water, ice as food, hoses, cross-connections, air gaps, backflow devices, and grease systems', null, 0),
  ('e332390c-9728-450b-8fae-1fab2c261d5b', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', 'a1aa7c6d-0862-451c-9eac-2c72277fc15a', 'concept'::public.curated_course_node_type, 'Sewage backups, drain overflows, condensation, leaks, and standing water', null, 1);
