  ('0b7ec4ca-cceb-4e59-b598-ec40ebad1625', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', null, 'topic'::public.curated_course_node_type, 'HACCP, Preventive Controls, and Active Managerial Control', 'This section turns hazard knowledge into a preventive management system. Students learn to analyze processes, establish controls, verify performance, and take corrective action before unsafe food reaches a guest.', 9),
  ('b55b1175-5b48-49b6-b933-e158b5bc2212', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', '0b7ec4ca-cceb-4e59-b598-ec40ebad1625', 'subtopic'::public.curated_course_node_type, 'Prerequisite programs and process mapping', 'Students first establish dependable basic conditions and a truthful picture of how food flows.', 0),
