  ('a221930b-7118-4f46-b6e7-b86cc5f9fe65', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', 'b55b1175-5b48-49b6-b933-e158b5bc2212', 'concept'::public.curated_course_node_type, 'Product description, intended use, consumers, flow diagram, on-site confirmation, and process categories', null, 1),
  ('db656796-6d5c-46ba-bd7b-d6b08657da72', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', 'b55b1175-5b48-49b6-b933-e158b5bc2212', 'concept'::public.curated_course_node_type, 'Operational prerequisite programs and jurisdictional terminology', null, 2),
  ('f7fc174e-0999-4454-9e30-b0579bea5c30', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', '0b7ec4ca-cceb-4e59-b598-ec40ebad1625', 'subtopic'::public.curated_course_node_type, 'Seven HACCP principles', 'This subtopic teaches a disciplined method for significant hazard control.', 1),
  ('d359823a-cdae-44d4-83f4-fc4ea974dbfa', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', 'f7fc174e-0999-4454-9e30-b0579bea5c30', 'concept'::public.curated_course_node_type, 'Hazard analysis and control-measure selection', null, 0),
  ('72711732-6a54-4730-a37f-20e027b4e791', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', 'f7fc174e-0999-4454-9e30-b0579bea5c30', 'concept'::public.curated_course_node_type, 'Critical control points, validated critical limits, monitoring, corrective action, verification, and records', null, 1),
  ('d0c614d2-c95c-4aa4-a461-6a00bb8d359a', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', 'f7fc174e-0999-4454-9e30-b0579bea5c30', 'concept'::public.curated_course_node_type, 'Validation versus verification; deviations, disposition, and reassessment', null, 2),
  ('e474b76f-7774-447e-b1fd-29abd1d2ecf9', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', '0b7ec4ca-cceb-4e59-b598-ec40ebad1625', 'subtopic'::public.curated_course_node_type, 'Active managerial control', 'Students learn to manage the common risk factors every shift through policies, training, monitoring, and corrective action.', 2),
  ('9537d14d-359d-406b-9f26-e41b736c5585', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', 'e474b76f-7774-447e-b1fd-29abd1d2ecf9', 'concept'::public.curated_course_node_type, 'Demonstration of knowledge, employee health, approved sources, cooking, holding, contaminated equipment, and other risk factors', null, 0),
  ('019d8630-d4c3-41b0-83e2-9d9555a4a307', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', 'e474b76f-7774-447e-b1fd-29abd1d2ecf9', 'concept'::public.curated_course_node_type, 'Daily checks, manager observations, exception reporting, and ownership', null, 1),
  ('ff0216f2-5084-4c7e-b4a5-f85ed634b816', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', 'e474b76f-7774-447e-b1fd-29abd1d2ecf9', 'concept'::public.curated_course_node_type, 'Trend analysis, focused interventions, accountability, and continuous improvement', null, 2),
  ('b84a6e73-1e0c-4bbb-80fc-f14a62e40dd5', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', '0b7ec4ca-cceb-4e59-b598-ec40ebad1625', 'subtopic'::public.curated_course_node_type, 'Special processes and variances', 'This subtopic makes clear that reduced-oxygen packaging, curing, acidification, sprouting, and other processes require specialized controls and often regulatory approval.', 3),
  ('e5c9a374-4cb1-4562-81d1-29a6a5d26f4a', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', 'b84a6e73-1e0c-4bbb-80fc-f14a62e40dd5', 'concept'::public.curated_course_node_type, 'Variance triggers and HACCP plan requirements', null, 0),
  ('a735332e-f916-4278-9495-8ce0f51e3980', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', 'b84a6e73-1e0c-4bbb-80fc-f14a62e40dd5', 'concept'::public.curated_course_node_type, 'Reduced-oxygen packaging, sous vide, cook-chill, smoking for preservation, curing, custom processing, live molluscan shellfish tanks, sprouting, and acidification', null, 1),
  ('44431d24-fe1c-438a-acfb-c4228414308e', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', 'b84a6e73-1e0c-4bbb-80fc-f14a62e40dd5', 'concept'::public.curated_course_node_type, 'Scientific support, validation, labeling, shelf life, monitoring, records, and regulator consultation', null, 2),
  ('cab95990-0e69-4224-91c4-72c08f26623d', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', null, 'topic'::public.curated_course_node_type, 'Inspection, Compliance, Documentation, and Corrective Action', 'Regulatory inspections are snapshots; food safety must be managed continuously. Students learn to prepare through daily control, communicate professionally, interpret findings, and close the loop on violations.', 10),
  ('a54a16f0-f5c8-4177-8b43-90c251c77ab2', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', 'cab95990-0e69-4224-91c4-72c08f26623d', 'subtopic'::public.curated_course_node_type, 'Risk-based inspection and regulatory interaction', 'Students understand inspection purpose, methods, evidence, and professional responsibilities.', 0),
  ('0e3856f4-d5d5-40db-a4da-b73529c8eb02', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', 'a54a16f0-f5c8-4177-8b43-90c251c77ab2', 'concept'::public.curated_course_node_type, 'Preoperational and operational observations, temperatures, interviews, records, sampling, and embargo/hold authorities', null, 0),
  ('4327c2d8-5095-4a29-8db4-5c3be617d09e', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', 'a54a16f0-f5c8-4177-8b43-90c251c77ab2', 'concept'::public.curated_course_node_type, 'Priority classifications, compliance timeframes, follow-up, enforcement, appeal, and due process', null, 1),
  ('a2157646-89c3-49cf-979f-15ff70e77cb3', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', 'a54a16f0-f5c8-4177-8b43-90c251c77ab2', 'concept'::public.curated_course_node_type, 'Cooperation, truthful records, employee support, note taking, and escalation to leadership/counsel', null, 2),
  ('174aa235-cffb-42e9-862f-a46f5386eabe', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', 'cab95990-0e69-4224-91c4-72c08f26623d', 'subtopic'::public.curated_course_node_type, 'Records and evidence', 'This subtopic focuses on concise, accurate documentation that supports control rather than paperwork for its own sake.', 1),
  ('895dabed-61e8-4e90-bde7-48e17d3a4aa2', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', '174aa235-cffb-42e9-862f-a46f5386eabe', 'concept'::public.curated_course_node_type, 'Receiving, temperature, cooling, sanitizer, employee health, training, cleaning, pest, maintenance, allergen, and corrective-action records', null, 0),
  ('4ae0fc75-181d-43e4-aab2-e64d5e905e9c', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', '174aa235-cffb-42e9-862f-a46f5386eabe', 'concept'::public.curated_course_node_type, 'Legibility, timestamps, instrument/lot identification, signatures, electronic controls, retention, and privacy', null, 1),
  ('5e0fb597-0da9-4a75-8123-ece2d91f5d4e', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', '174aa235-cffb-42e9-862f-a46f5386eabe', 'concept'::public.curated_course_node_type, 'Review by exception, falsification risk, record availability, and trend analysis', null, 2),
  ('985d9da8-e3a3-4933-b601-0939ab683dcc', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', 'cab95990-0e69-4224-91c4-72c08f26623d', 'subtopic'::public.curated_course_node_type, 'Corrective and preventive action', 'Students move beyond fixing the immediate symptom to address system causes and verify effectiveness.', 2),
  ('970aa245-96f6-4ca8-aa09-48a0213bbebb', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', '985d9da8-e3a3-4933-b601-0939ab683dcc', 'concept'::public.curated_course_node_type, 'Immediate control, affected-food assessment, hold/discard/rework only when approved, and documentation', null, 0),
  ('9517a1f3-e737-40ff-a8ea-7eca3d8a9f76', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', '985d9da8-e3a3-4933-b601-0939ab683dcc', 'concept'::public.curated_course_node_type, 'Five whys, fishbone, process mapping, contributing factors, and environmental antecedents', null, 1),
  ('8b4d5046-bb89-47c2-830a-9d8f16deca03', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', '985d9da8-e3a3-4933-b601-0939ab683dcc', 'concept'::public.curated_course_node_type, 'Owner, due date, preventive change, effectiveness check, recurrence monitoring, and closure', null, 2),
  ('ac175b01-2988-4009-8901-19f71e80454b', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', null, 'topic'::public.curated_course_node_type, 'Food Safety Management Systems, Culture, and Training', 'World-class operations treat food safety as a managed organizational value. This section develops leadership practices that align policies, resources, behavior, data, and accountability.', 11);
