  ('ba6da822-2a29-40ec-8d8f-f1a62b90ee2f', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', 'f60f55fe-4e25-4f1b-baef-8fcb74344731', 'concept'::public.curated_course_node_type, 'Continuing education, code updates, emerging hazards, and communities of practice', null, 2),
  ('656c3108-4b49-4b7d-b655-f8e78cc8296f', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', null, 'topic'::public.curated_course_node_type, 'Special Operations: Catering, Buffets, Delivery, Mobile, and High-Risk Service', 'Hospitality operations often move food away from the controlled kitchen. This section applies core principles to changing locations, delayed service, transportation, temporary utilities, and vulnerable populations.', 12),
