  ('d46d58b9-c9c3-40ff-b457-0f020181ccd5', 'c8d9e0f1-2a3b-4c13-8d52-6e7f8a9b0c03', '40b538cb-dfb3-45ba-8c65-325bdd384016', 'concept'::public.curated_course_node_type, 'Temporary handwashing, warewashing, protected service, power, water, waste, and pest controls', null, 1),
